    h.log(`${id} could not start (${n}/${max}): ${x}`); if (n >= max) await stop(h, `${id} could not start ${n} times: ${String(x).slice(0, 120)}`)
  } finally { inflight.delete(k); await settleIntent(h, n) }
}

