const pidOf = async (h: Host) => (proc.pid ??= await h.run(['sh', '-c', 'echo "$(uname -n) $PPID"']).then(r => (r.exitCode ? '' : r.stdout.trim()), () => ''))
type Alive = Record<string, { p: string; at: number; pid?: string }>
const ALIVE = 30_000
