  if (steps.length) await queueBrief(h, `Continue plan ${p.id}: ${steps.join('; ')}.`); else if (!canSpawn(h) && (await idle(h))) await queueBrief(h, IDLE)   // a typed /cadre is a frame that starts them itself; a press is not
