  if (b === 'recut') {
    await cutEpic(h, p.id, (await cfgOf(h)).branches.dev)
    await h.board.update(x => (x.plan ? { ...x, plan: { ...x.plan, state: epicNext(x.plan.state, 'recut') ?? x.plan.state, flags: (x.plan.flags ?? []).filter(f => f !== 'lost-epic') } } : x))
    await emit(h, 'flag.resolved', { taskId: p.id, flag: 'lost-epic' }, { taskId: p.id }); return { text: `Epic ${p.id}: ${p.epicBranch} re-cut from dev.` }
  }
  for (const t of s.tasks.filter(x => !['done', 'cancelled'].includes(x.state))) { await apply(h, { kind: 'cancel', id: t.id, at: await h.now(), actor: 'human' }, pipeOf(reg)); await store.close(t.id, { outcome: 'cancelled', note: 'epic cancelled' }).catch(() => {}) }
  await store.close(p.id, { outcome: 'cancelled', note: 'epic cancelled' }).catch(() => {})
  await h.board.update(x => ({ ...x, plan: null, epic: null, tasks: [], approval: { planId: null, missing: [] }, sheet: [] }) as typeof x); return { text: `Epic ${p.id} cancelled.` }
}

// /cadre restore [<name>] (13.7): re-apply a quarantined stash (kept in the stash list, never dropped)
export async function restore(h: Host, name?: string): Promise<Out> {
  const q = ((await h.store.get(await scoped(h, 'quarantine'))) as { name: string; tree: string; paths: string[] }[] | undefined) ?? [], e = name ? q.find(x => x.name === name) : q[q.length - 1]
  if (!e) return refuse(`no quarantined entry${name ? ` ${name}` : ''}${q.length ? `; known: ${q.map(x => x.name).join(', ')}` : ''}`)
  const ref = (await h.run(['git', '-C', e.tree, 'stash', 'list', '--format=%gd %s'])).stdout.split('\n').find(l => l.endsWith(e.name))?.split(' ')[0]
  if (!ref) return refuse(`${e.name}: the stash is gone`)
  const r = await G.op(h, () => h.run(['git', '-C', e.tree, 'stash', 'apply', ref]))
  return r.exitCode ? refuse(`${e.name}: ${r.stderr.trim().slice(0, 200)}`) : { text: `Restored ${e.paths.length} path(s) of ${e.name} into ${e.tree} (the stash is kept).` }
}

// route = the handler for everything else (commands/cadre.ts); a gate command from any origin but the ask dialog (or a Settings press) is refused before it (ADR 0012)
export async function dispatch(h: Host, c: Command, route: Route): Promise<Out> {
  if (c.schemaVersion !== 1) return refuse('unsupported command schemaVersion')
  const why = gated(c) ? isHuman(c.origin) : ['init', 'setup'].includes(c.cmd) && !['composer', 'press', 'dialog'].includes(c.origin.kind) ? `origin ${c.origin.kind} cannot start ${c.cmd}` : null
  if (why) return refuse(why)
  if ((c.cmd === 'init' || c.cmd === 'setup') && c.args[0] === 'cancel') { await settleIf(h, 'init:'); await RUN.cancel?.(h, c.cmd); return { text: `${c.cmd}: cancelled` } }   // the decision's Cancel: ends the run and its lease
  if (c.cmd === 'approve') return approve(h, c)
  if (c.cmd === 'reject') return reject(h, c)
  return route(h, c)
}

// The dialog's answer to decision `id`, option `key`, asked with `hash` (+ the values typed for its fields). The decision changing while the dialog was open refuses it (the dialog
// re-asks); otherwise the option's command runs as origin dialog. commands/cadre passes its router.
export async function answer(h: Host, id: string, key: string, hash: string, route: Route, vals: Record<string, string> = {}): Promise<Out> {
  const d = ((await h.board.read()).decisions ?? []).find(x => x.id === id), o = d?.options.find(x => x.key === key)?.run
  if (!d && id.startsWith('plan:') && (await drafting(h))) return refuse('Claude is still changing the plan; it comes back when Claude is done')   // the dialog does not re-ask it
  if (!d || d.hash !== hash || !o) return refuse('it changed; review again')   // nothing runs
  const [cmd, ...args] = o.split(/\s+/).filter(Boolean).flatMap(a => (a === '{fields}' ? (d.fields ?? []).map(f => `${f.key}=${vals[f.key] ?? f.value ?? ''}`) : [a]))   // fields as k=v argv elements
  await h.ui.update(u => ({ ...u, answering: id }))   // while its command runs (an approval: seconds of store calls) no surface offers "press 1" on it again (ui/model.attention)
  try { const out = await dispatch(h, { schemaVersion: 1, cmd, args, origin: { kind: 'dialog' } }, route); await DRIVE.kick?.(h).catch(e => h.log(`drive: ${e}`)); return out } catch (x) { return { text: `cadre: ${(x as Error).message}` } } finally { await h.ui.update(u => ({ ...u, answering: undefined })) }
}

files.core/effect.ts:
// L3 effect check (DESIGN 13.1): fingerprint, in-flight window attribution, stash quarantine, flags, protected-ref restore by CAS. Slot #6 `wrap` (+ later duties).
// Git runs through the injected h.run (ADR 0003): kit-testable with a scripted run.
import { modelText } from './say'
import { askByTool, askCard, shown } from './asks'
import type { Hook, Host } from '../types'
import type { TaskStore } from '../task-management/store'
import * as G from './git'
import { emit } from './events'
import { scoped } from '../commands/init'
import { inputPath, policyOf } from '../policy/guards'
import { drainDelta, idsIn } from './briefs'
import { logCall } from './specview'
import { UI } from './board'
import { noReportCard } from './render'

const WRITERS = ['Edit', 'Write', 'NotebookEdit', 'Bash', 'PowerShell', 'Monitor']
export const writes = (tool: string) => WRITERS.includes(tool) || (tool.startsWith('mcp__') && !tool.startsWith('mcp__cadre__'))   // no write capability in any allowlist -> skipped
const STATUS = ['status', '--porcelain=v2', '-z', '--', '.', ':(exclude).cadre', ':(exclude).beads', ':(exclude).claude/settings.local.json']
const git = (h: Host, tree: string, ...a: string[]) => h.run(['git', '-C', tree, ...a])

// Records of `status --porcelain=v2 -z`, keyed by the record text -> its path (a rename record owns the following origin path).
export function parse(s: string): Map<string, string> {
  const r = s.split('\0').filter(Boolean), m = new Map<string, string>()
  for (let i = 0; i < r.length; i++) {
    const t = r[i][0], f = r[i].split(' ')
    if (t === '2') { m.set(`${r[i]}\0${r[i + 1]}`, f.slice(9).join(' ')); i++ } else m.set(r[i], t === '?' || t === '!' ? r[i].slice(2) : f.slice(t === 'u' ? 10 : 8).join(' '))
  }
  return m
}
// New records, plus paths whose content hash moved (status records carry HEAD/index hashes, not the worktree's: a re-edit of a dirty file changes no record)
const changed = (before: string | undefined, now: string, hb = '{}', hn = '{}'): string[] => {
  const b = parse(before ?? ''), o = JSON.parse(hb) as Record<string, string>, n = JSON.parse(hn) as Record<string, string>
  return [...new Set([...parse(now)].filter(([k, p]) => !b.has(k) || (n[p] !== undefined && o[p] !== n[p])).map(([, p]) => p))]
}
const refMap = (s: string) => new Map(s.split('\n').filter(Boolean).map(l => [l.slice(41), l.slice(0, 40)] as const))

// Fingerprint of the given trees (+ the protected-ref list when the main checkout is in scope).
async function fingerprint(h: Host, trees: string[], repo: string): Promise<Record<string, string>> {
  const fp: Record<string, string> = {}
  for (const t of trees) {
    fp[`s:${t}`] = (await git(h, t, ...STATUS)).stdout
    fp[`h:${t}`] = (await git(h, t, 'rev-parse', 'HEAD')).stdout.trim()
    const ps = [...new Set(parse(fp[`s:${t}`]).values())].filter(p => !p.endsWith('/')), r = ps.length ? await git(h, t, 'hash-object', '--', ...ps) : undefined
    const hs = r && !r.exitCode ? r.stdout.split('\n').filter(Boolean) : []   // a deleted path makes the batch fail: that tree keeps record-level detection
    fp[`c:${t}`] = JSON.stringify(hs.length === ps.length ? Object.fromEntries(ps.map((p, i) => [p, hs[i]])) : {})
  }
  if (trees.includes(repo)) fp.refs = (await git(h, repo, 'for-each-ref', '--format=%(objectname) %(refname)', 'refs/heads')).stdout
  return fp
}

async function raise(h: Host, flag: string, taskId: string, info: { ref?: string; old?: string; tip?: string } = {}, text = flag) {
  if ((await h.git.read()).flags?.[flag]) return
  await h.git.update(g => ({ ...g, flags: { ...g.flags, [flag]: info } }))
  await emit(h, 'flag.raised', { taskId, flag }, { taskId: taskId || undefined })
  h.toast(`cadre: ${text}`)
}

const isProtected = (branch: string, protect: string[] = ['main', 'dev'], epicPrefix = 'epic/') => protect.includes(branch) || branch.startsWith(epicPrefix) || branch.startsWith('milestone/')

// One audit: scope = main + caller's worktree (sandbox on) or everything (sweep / degraded / effectCheck always).
export async function audit(h: Host, caller: string | null): Promise<void> {
  const g = await h.git.read(), pol = await policyOf(h)
  if (g.busy || !pol.repo || pol.effectCheck === 'off') return
  const binds = await h.bind.read()
  const owners: Record<string, string[]> = { [pol.repo]: [] }
  for (const [id, b] of Object.entries(binds)) if (b.role !== 'tester') owners[b.worktree] = [...(owners[b.worktree] ?? []), id]   // views are not git trees (3.5.3); a worker and its reviewer share the worktree (live 0.9.0: a reworking worker's write was blamed on the idle reviewer and quarantined)
  const full = caller === null || pol.effectCheck === 'always' || (await h.board.read()).containment.state !== 'contained' || !binds[caller]
  const scope = full ? Object.keys(owners) : [...new Set([pol.repo, binds[caller!].worktree])]
  const now = await fingerprint(h, scope, pol.repo), base = g.fp
  { const g2 = await h.git.read(); if (g2.busy || g2.epoch !== g.epoch) return }   // a cadre git op ran while this one looked (a close at another agent's turn end, ADR 0018): judge nothing; its epoch re-baselines the next look
  const open = [...new Set(Object.values(g.win?.open ?? {}))]
  const save = (fp: Record<string, string>, loops: string[]) => h.git.update(x => ({ ...x, fp: { ...x.fp, ...fp, epoch: String(x.epoch) }, win: { open: x.win?.open ?? {}, loops } }))   // the window restarts at each audit with the calls still in flight
  if (!base || base.epoch !== String(g.epoch)) return void (await save(now, open))   // first sight or a mod git op: re-baseline, no verdict
  const loops = g.win?.loops ?? [], agentLoop = loops.some(l => l !== ''), after = { ...now }
  for (const t of scope) {
    if (base[`s:${t}`] === undefined) continue
    const paths = changed(base[`s:${t}`], now[`s:${t}`], base[`c:${t}`], now[`c:${t}`]), o = owners[t] ?? []
    if (!paths.length) continue
    const tid = o.length ? binds[o[0]].taskId : ''
    const locked = pol.locks?.[tid] ?? []
    if (!o.length) {   // the main checkout is the human's tree: never stashed (13.7). A human edit only warns; an agent-attributed one blocks merges until `resolve git keep`
      if (agentLoop) await raise(h, 'git:main-dirty:agent', '', {}, 'main checkout changed while an agent ran')
      else h.toast('cadre: main checkout changed outside cadre')
      continue
    }
    const bad = o.some(x => loops.includes(x)) ? paths.filter(p => locked.some(l => p === l || l.endsWith('/' + p))) : paths   // rule 1
    if (!bad.length) continue
    const ts = await h.now(), name = `cadre-q-${tid || 'main'}-${ts}`
    const r = await git(h, t, 'stash', 'push', '-u', '-m', name, '--', ...bad)
    await raise(h, r.exitCode ? `quarantine-failed:${tid || 'main'}` : `quarantine:${tid || 'main'}`, tid, {}, `${bad.length} path(s) quarantined (${name})`)
    if (!r.exitCode) { const qk = await scoped(h, 'quarantine'), q = ((await h.store.get(qk)) as unknown[]) ?? []; await h.store.set(qk, [...q, { name, tree: t, paths: bad, ts }]); Object.assign(after, await fingerprint(h, [t], pol.repo)) }
  }
  if (scope.includes(pol.repo) && base.refs !== undefined) {   // rule 3: protected refs moved outside a cadre merge (epoch unchanged)
    const was = refMap(base.refs), is = refMap(now.refs)
    for (const [ref, old] of was) {
      const br = ref.replace(/^refs\/heads\//, ''), tip = is.get(ref)
      if (tip !== old && isProtected(br, pol.protect, pol.epicPrefix)) await raise(h, agentLoop ? `git:${br}:agent` : `git:${br}`, '', { ref, old, tip }, `protected branch ${br} moved outside cadre`)
    }
  }
  await save(after, open)
}

// #6 tool.call wrap: L3 window + audit for writers; then the delta drain (4.3), the foreground result card (S39), the tester call log (3.5.2).
export const wrap: Hook = async (h, e, next) => {
  const r = await (writes(e.tool) ? audited(h, e, next) : next(e))
  try { return await after(h, e, r) } catch (x) { h.log(`wrap after-call failed: ${x}`); return r }
}
async function after(h: Host, e: any, r: any): Promise<any> {
  if (!e.agentId) {   // main's foreground Agent call: the task's card replaces the hand-back text (r.result.content[0].text, S39)
    if (e.tool !== 'Agent' || !r?.result?.content?.[0]) return r
    const s = await h.board.read(), [id] = idsIn(String(e.prompt ?? e.input?.prompt ?? ''), s.tasks.map(t => t.id)), t = s.tasks.find(x => x.id === id)
    const ask = !t && (await askByTool(h, e.tool_use_id))   // a marker-less explorer: its card, never its text
    if (ask) { await shown(h, ask[0], ask[1]); return { ...r, result: { ...r.result, content: [{ ...r.result.content[0], text: modelText('card', askCard(ask[1]).replaceAll('\n', ' · ')) }, ...r.result.content.slice(1)] } } }
    if (!t?.card) return r
    if (e.tool_use_id) await UI.mapCard?.(h, e.tool_use_id, t.id)
    const b = Object.values(await h.bind.read()).find(x => x.taskId === t.id && x.step === t.step && ['tester', 'worker', 'reviewer'].includes(x.role))   // an agent bound at the step the task is still at: it stopped without reporting (its stop is observed after this result returns)
    const text = b ? noReportCard(t, b.role, b.step) : t.card
    return { ...r, result: { ...r.result, content: [{ ...r.result.content[0], text: modelText('card', text.replace('\n', ' · ')) }, ...r.result.content.slice(1)] } }
  }
  const b = (await h.bind.read())[e.agentId]
  if (b?.role === 'tester') await logCall(h, e.agentId, { tool: e.tool, path: inputPath(e.tool, e.input ?? e, b.worktree), outcome: r?.deny ? String(r.deny) : r?.error ? 'error' : 'ok' })
  const d = b && (await drainDelta(h, e.agentId))
  return d ? { ...r, context: [...(r?.context ?? []), modelText('context', d)] } : r
}
async function audited(h: Host, e: any, next: (e: any) => any) {
  const loop = e.agentId ?? '', id = e.tool_use_id ?? h.rand(4)
  await h.git.update(g => ({ ...g, win: { loops: [...new Set([...(g.win?.loops ?? []), loop])], open: { ...g.win?.open, [id]: loop } } }))
  try { return await next(e) } finally {
    await h.git.update(g => { const { [id]: _d, ...open } = g.win?.open ?? {}; return { ...g, win: { loops: g.win?.loops ?? [], open } } })   // this call is over, but stays in the window it is about to be audited in
    await audit(h, loop).catch(x => h.log(`effect audit failed: ${x}`))
  }
}

// Full sweep: at every turn.complete (core/close.observe calls it) and before every merge.
export const sweep = (h: Host) => audit(h, null)

// `resolve git keep|restore <flag>`: keep accepts the move; restore saves the tip to refs/cadre/quarantine and CAS-moves the ref back (Q4).
export async function resolveGit(h: Host, flag: string, how: 'keep' | 'restore'): Promise<{ ok: boolean; error?: string }> {
  const f = (await h.git.read()).flags?.[flag], pol = await policyOf(h)
  if (!f || !pol.repo) return { ok: false, error: `no open flag ${flag}` }
  if (how === 'restore') {
    if (!f.ref || !f.old) return { ok: false, error: `${flag} cannot be restored` }
    if (f.tip) {
      const s = await git(h, pol.repo, 'update-ref', `refs/cadre/quarantine/${f.ref.replace(/^refs\/heads\//, '')}-${await h.now()}`, f.tip)
      if (s.exitCode) return { ok: false, error: s.stderr }
    }
    const r = await git(h, pol.repo, 'update-ref', f.ref, f.old, ...(f.tip ? [f.tip] : []))   // CAS: only if still at the tip we saw
    if (r.exitCode) return { ok: false, error: `ref moved again: ${r.stderr}` }
  }
  const refs = (await git(h, pol.repo, 'for-each-ref', '--format=%(objectname) %(refname)', 'refs/heads')).stdout
  await h.git.update(g => { const { [flag]: _d, ...flags } = g.flags ?? {}; return { ...g, flags, fp: { ...g.fp, refs } } })
  await emit(h, 'flag.resolved', { taskId: '', flag })
  return { ok: true }
}

// ---- checkpoint (8.4): commit a dirty worktree as wip; dirty locked paths refuse it and raise locked-dirty ----
export async function checkpoint(h: Host, store: TaskStore, actor: string, taskId: string, wt: string): Promise<string | null> {
  const dirty = (await h.run(['git', '-C', wt, 'status', '--porcelain', '-z'])).stdout.split('\0').filter(l => l.length > 3).map(l => l.slice(3))   // untrimmed: ' M a' keeps its column
  if (!dirty.length) return null
  const locks = (await policyOf(h)).locks?.[taskId] ?? []
  if (dirty.some(p => locks.some(l => l === p || l.endsWith(`/${p}`) || p.startsWith(`${l.replace(/\/$/, '')}/`)))) {
    await h.board.update(s => ({ ...s, tasks: s.tasks.map(t => (t.id === taskId && !t.flags.includes('locked-dirty') ? { ...t, flags: [...t.flags, 'locked-dirty'] } : t)) }))
    await emit(h, 'flag.raised', { taskId, flag: 'locked-dirty' }, { taskId }); return null
  }
  const cp = await G.op(h, () => G.commitAll(h.run, wt, `wip(${taskId}): checkpoint`))
  if (cp) await store.setMeta(taskId, { 'cadre.checkpoint': cp }, actor)
  return cp ?? null
}

files.tools/index.ts:
// The 3 MCP tools (DESIGN 5.2, 6.2, 6.6): report, inspect, run_check; strict schemas with schemaVersion, isDeferred:false. Registered in session.start from SPECS (register.ts).
// Handlers answer `{result}` (an `error: …` text is a refusal the agent can retry). Descriptions are byte-stable.
import { modelText } from '../core/say'
import type { Hook, Host } from '../types'
import { resolveDeps, type Deps } from '../core/admission'
import { raise, report, runCheck } from '../core/close'
import { warm } from '../core/session'
import { askAnswer, askOf } from '../core/asks'
import { planned } from '../core/planner'
import { refuse, tried, validateReport } from '../core/validate'
import * as G from '../core/git'
import { charge, runOf, step } from '../core/lifecycle'

export const TOOLS = ['report', 'inspect', 'run_check'] as const
const S = { type: 'string' }, ARR = { type: 'array' }
const V = { type: 'integer', enum: [1] }
export const SPECS = [
  { name: 'report', isDeferred: false, description: 'Finish your step. Worker: {schemaVersion:1,role:"worker",outcome:"done"|"blocked"|"spec_change",summary,reason?,risks?,questions?}. Tester: role "tester", outcome "done", summary, tests[{path,name,scenario}], run{command[],junit?,cwd?} (the argument list that runs only your tests). Reviewer: role "reviewer", verdict "pass"|"changes", summary, findings[{severity,file,line?,issue,fix?}], coverage[{scenario,test?,ok}], contractStatus[{name,ok}]. Explorer: role "explorer", answer, citations[{path,line}]. Planner: role "planner", summary, tasks[{subject,description,metadata,after?}]. Call it once, then stop.',
    inputSchema: { type: 'object', additionalProperties: false, required: ['schemaVersion', 'role'], properties: { schemaVersion: V, role: { type: 'string', enum: ['worker', 'tester', 'reviewer', 'explorer', 'planner'] }, outcome: { type: 'string', enum: ['done', 'blocked', 'spec_change'] }, summary: S, reason: S, risks: ARR, questions: ARR, tests: ARR, run: { type: 'object' }, followups: ARR, verdict: { type: 'string', enum: ['pass', 'changes'] }, findings: ARR, coverage: ARR, contractStatus: ARR, answer: S, citations: ARR, tasks: ARR } } },
  { name: 'inspect', isDeferred: false, description: 'Read git facts of your task tree. what: status | files | log | diff | show. rev and path are optional; show needs a path. Output: exit, seconds, truncated, capped body.',
    inputSchema: { type: 'object', additionalProperties: false, required: ['what'], properties: { schemaVersion: V, what: { type: 'string', enum: ['status', 'files', 'log', 'diff', 'show'] }, task: S, rev: S, path: S } } },
  { name: 'run_check', isDeferred: false, description: 'Run a named check of your task package on your tree. Output: exit, seconds, truncated, capped body.',
    inputSchema: { type: 'object', additionalProperties: false, required: ['name', 'task'], properties: { schemaVersion: V, name: S, task: S } } },
] as const

const bad = (m: string) => `error: ${m}`

async function onReport(h: Host, d: Deps, agentId: string | undefined, r: any): Promise<string> {
  const key = `report:${agentId ?? 'main'}`
  if (!agentId) return bad('only a spawned agent reports')
  const no = async (m: string) => {   // a bound agent's refusals count on its run (and the task budget); anyone else's in ui.retries
    const s = (await step(h, agentId, { type: 'report.refused' }))?.state
    if (s?.state !== 'refused') return bad(await refuse(h, key, m))
    await charge(h, (await runOf(h, agentId))!.taskId, 'refusals'); return bad(tried(m, s.n, key))
  }
  const env = validateReport(r); if (env) return no(env)
  if (!(await h.bind.read())[agentId] && (await askOf(h, agentId))) return r.role === 'explorer' ? askAnswer(h, agentId, r) : bad('role: you are an explorer; report role "explorer" with answer and citations')
  if ((await h.bind.read())[agentId]?.role === 'planner') return r.role === 'planner' ? planned(h, d, agentId, r).then(async t => (await step(h, agentId, { type: t.startsWith('error') ? 'report.refused' : 'report.ok' }), t)) : bad('role: you are the planner; report role "planner" with tasks')   // a ready epic's planner (core/planner)
  const b = (await h.bind.read())[agentId], ok = async () => step(h, agentId, { type: 'report.ok', wait: (await h.board.read()).tasks.find(t => t.id === b?.taskId)?.state === 'blocked' })
  try {
    const text = await report(h, d, agentId, r); await ok(); return text
  } catch (x) {
    const msg = (x as Error).message, s = (await runOf(h, agentId))?.state, n = s?.state === 'refused' ? s.n : 0   // refusals so far, on its run
    // semantic (6.3) failures only; after limits.reportRetries the report is accepted unvalidated + flagged
    if (n >= d.cfg.limits.reportRetries && /^(findings|coverage|contractStatus|verdict)/.test(msg)) {
      await raise(h, b.taskId, 'report-unvalidated'); const text = await report(h, d, agentId, r, { lax: true }); await ok(); return text
    }
    return no(msg)
  }
}

const SAFE = /^[\w./@^~:{}+-]+$/
async function onInspect(h: Host, d: Deps, agentId: string | undefined, i: any): Promise<string> {
  const b = agentId ? (await h.bind.read())[agentId] : undefined, tree = b?.worktree || d.root, what = i.what
  if (!['status', 'files', 'log', 'diff', 'show'].includes(what)) return bad('what: expected status|files|log|diff|show')
  if (!agentId && !['status', 'files', 'log'].includes(what)) return bad('main may inspect status, files and log only')
  if (i.task && b && i.task !== b.taskId) return bad(`task: you are bound to ${b.taskId}`)
  const rev = i.rev as string | undefined, path = i.path as string | undefined
  if (path !== undefined && (typeof path !== 'string' || path.startsWith('/') || path.startsWith('-') || path.split('/').includes('..'))) return bad('path: expected a relative path inside your working directory, e.g. "src/a.ts"')
  if (rev !== undefined && (typeof rev !== 'string' || rev.startsWith('-') || !SAFE.test(rev) || !(await G.exists(h.run, tree, rev)))) return bad(`rev: ${JSON.stringify(rev)} is not a known commit`)
  const task = b ? await d.store.get(b.taskId) : undefined, C = task?.meta['cadre.sourceCommit'], base = task?.meta['cadre.base']
  if (rev && C && b?.role === 'reviewer' && !(await G.ok(h.run, tree, ['merge-base', '--is-ancestor', rev, C]))) return bad(`rev: ${rev} is outside the reviewed range (up to ${C.slice(0, 7)})`)
  const p = path ? ['--', path] : []
  const argv = what === 'status' ? ['status', '--short', ...p] : what === 'files' ? ['ls-tree', '-r', '--name-only', '--end-of-options', rev ?? C ?? 'HEAD', ...p]
    : what === 'log' ? ['log', '--oneline', '-n', '30', '--end-of-options', rev ?? C ?? 'HEAD', ...p] : what === 'diff' ? ['diff', '--end-of-options', rev ?? base ?? 'HEAD', C ?? 'HEAD', ...p]
    : ['show', '--end-of-options', `${rev ?? C ?? 'HEAD'}:${path ?? ''}`]
  if (what === 'show' && !path) return bad('path: show needs a path')
  const t0 = await h.now(), r = await h.run(['git', '-C', tree, ...argv]), out = r.stdout + r.stderr, cut = out.length > 16384
  let log = ''
  if (cut) { log = `${d.root}/.cadre/tmp/logs/inspect-${t0}.log`; await h.write(log, out).catch(() => { log = '' }) }
  return `exit=${r.exitCode} · ${Math.round(((await h.now()) - t0) / 1000)}s · truncated=${cut ? 'yes' : 'no'}\n${cut ? out.slice(-4096) : out}`
}

async function onCheck(h: Host, d: Deps, agentId: string | undefined, i: any): Promise<string> {
  const b = agentId ? (await h.bind.read())[agentId] : undefined
  if (!b || b.role === 'explorer' || b.role === 'tester') return bad('run_check is for a bound worker or reviewer')
  if (i.task !== b.taskId) return bad(`task: you are bound to ${b.taskId}`)
  if (typeof i.name !== 'string' || !i.name) return bad('name: expected a check name, e.g. "test"')
  const r = await runCheck(h, d, await d.store.get(b.taskId), b.worktree, i.name)
  return r.found ? r.text : bad(r.text)
}

export async function handleWith(h: Host, d: Deps, e: any): Promise<{ result: string }> {
  const i = e.input ?? e, id = e.agentId as string | undefined
  try {
    switch (String(e.tool).replace(/^mcp__cadre__/, '')) {
      case 'report': return { result: modelText('tool-result', await onReport(h, d, id, i)) }
      case 'inspect': return { result: modelText('tool-result', await onInspect(h, d, id, i)) }
      default: return { result: modelText('tool-result', await onCheck(h, d, id, i)) }
    }
  } catch (x) { return { result: modelText('tool-result', bad(String((x as Error).message ?? x))) } }
}
// tool.call for mcp__cadre__*: answer {result}.
export const handle: Hook = async (h, e, next) => (TOOLS.some(t => e.tool === `mcp__cadre__${t}`) ? (await warm(h), handleWith(h, await resolveDeps(h), e)) : next(e))

