// /cadre setup (once per machine) and /cadre doctor (read-only diagnosis). ADR 0007, 0010: setup's fixing is done by Claude (guides/setup.md, commands/agentrun);
// this file holds the machine CHECKS both share. The command text is ONE line; the report goes to the human surface only (pane tab "doctor" + ui.log).
import type { Host } from '../types'
import type { Config } from '../config'
import { fnv1a64, leaseLive } from '../core/board'
import { cfgOf, initConfirm, initPropose, storeOf } from '../core/dispatch'
import { exists, identity, jailMode, ok as gitOk } from '../core/git'
import { wtRootOf } from '../core/branches'
import { qk } from '../core/session'
import { assess } from '../policy/containment'
import { policyOf } from '../policy/guards'
import { apply as mapply, plan as mplan } from '../policy/settings'
import { call } from '../task-management/protocol'
import { openPane } from '../ui/index'
import { BD_BLOCK, progress, scoped, type Item } from './init'
import { prefsItem, prefsRow } from './prefs'
import { doctorRows } from '../config/route'
import { runOf } from '../core/lifecycle'
import { BdStore } from '../task-management/adapters/beads/store'
import { dirOf, moveStore } from '../task-management/adapters/beads/layout'

export type Row = ['ok' | 'warn' | 'crit', string, string?]   // level, line, fix (a command for the human)
const PIN = '2.1.295', EXITS = '2.1.299', STAMP = 'cadre:setup', USER_CARD = 91, STORE_CARD = 92, PATCH = { env: { CLAUDE_CODE_ENABLE_TODO_TOOLS: '1' } }
const ver = (s: string) => s.match(/\d+(\.\d+)+/)?.[0] ?? ''
const atLeast = (v: string, min: string) => { const a = v.split('.').map(Number), b = min.split('.').map(Number); for (let i = 0; i < 3; i++) if ((a[i] ?? 0) !== (b[i] ?? 0)) return (a[i] ?? 0) > (b[i] ?? 0); return true }
// The oldest Claude Code cadre runs on: 2.1.295 added Button children (every press in the band and the pane; older builds throw "needs a label" and nothing
// draws), $.ui.notify; 2.1.293 isDeferred, 2.1.292 workflow agents at agent.spawn, 2.1.289 one agent id across hook events. Older: cadre stays off, says so (register.ts).
export const MIN_CC = '2.1.295'
export const tooOld = (v: string) => !!ver(v) && !atLeast(ver(v), MIN_CC)
export const oldLine = (v: string) => `cadre needs Claude Code ≥ ${MIN_CC}; you have ${ver(v)} · update with: claude update`

// ---- machine checks (shared by setup and doctor); every probe goes through h.run so tests inject fixtures. A row's fix is the command Claude (or, for sudo, the human) runs ----
const BD_SH = 'curl -fsSL https://raw.githubusercontent.com/gastownhall/beads/main/scripts/install.sh | bash'
// a human-run fix is a script under <cache>/cadre/fix (0700, harmless until run); the card and the follow-up only ever show the ONE short line that runs it (ADR 0007, 0.5.1)
export type Script = { path: string; text: string; run?: string; full?: string; exec?: true }   // run = the short line that runs it; full = the same fix as one copy-safe command
export async function machine(h: Host, cfg: Config): Promise<{ rows: Row[]; facts: Record<string, string>; scripts: Script[] }> {
  const r = (argv: string[]) => h.run(argv, { timeoutMs: 5000 }).catch(() => undefined), text = (x?: { stdout: string; stderr: string }) => `${x?.stdout}${x?.stderr}`, out = async (argv: string[]) => (await r(argv))?.stdout.trim() ?? ''
  const mac = (await r(['uname', '-s']))?.stdout.trim() === 'Darwin', pm = mac ? 'brew install' : 'apt install', rows: Row[] = [], facts: Record<string, string> = {}, scripts: Script[] = []
  const add = (x: Row): void => { rows.push(x) }
  const home = await h.home(), dir = `${(await h.env()).XDG_CACHE_HOME || `${home}/.cache`}/cadre/fix`, shown = dir.startsWith(`${home}/`) ? `~${dir.slice(home.length)}` : dir
  const fix = (name: string, why: string, cmd: string, root = true): string => {
    const run = `${root ? 'sudo ' : ''}sh ${shown}/${name}.sh`
    scripts.push({ path: `${dir}/${name}.sh`, exec: true, run, full: `${root ? 'sudo ' : ''}sh -c '${cmd.split('\n').join(' && ').replaceAll("'", "'\\''")}'`, text: `#!/bin/sh\n# cadre setup: ${why}\n# Run it once, yourself: ${run}\nset -eu\n${cmd}\n` })
    return `! ${run}`
  }
  facts.cc = (await h.version?.().catch(() => '')) ?? ''
  const cmp = ver(facts.cc) && !atLeast(PIN, ver(facts.cc)) ? 'newer than' : 'older than'
  add(!facts.cc ? ['warn', 'Claude Code version unreadable'] : tooOld(facts.cc) ? ['crit', oldLine(facts.cc), 'claude update'] : facts.cc === PIN ? ['ok', `Claude Code ${PIN} (the pinned build)`] : ['warn', `Claude Code ${facts.cc}: ${cmp} the tested ${PIN}; ${cmp === 'newer than' ? 'usually fine' : 'update it with claude update'}`])
  if (facts.cc && !atLeast(EXITS, ver(facts.cc))) add(['warn', `an agent that is done is ended by cadre itself; that is tested up to Claude Code ${EXITS} (yours: ${facts.cc})`])   // exit rule 5 (forced exit), S0 on 2.1.295 and 2.1.299
  const inj = ((await h.store.get(await scoped(h, 'injected'))) as string[] | undefined) ?? []; if (inj.length) add(['warn', `tools Claude Code gave the agents that cadre does not know: ${inj.join(', ')}`])   // exit rule 3: observed, judged like any other call
  const g = await r(['git', '--version']), gv = ver(text(g))
  add(!g || g.exitCode || !gv ? ['crit', 'git not found', fix('git', 'installs git (needed for worktrees).', `${pm} git`, !mac)] : atLeast(gv, '2.17') ? ['ok', `git ${gv}`] : ['crit', `git ${gv} is too old for worktrees`, fix('git', 'upgrades git to 2.17 or newer (needed for worktrees).', `${pm} git`, !mac)])
  const id = g && !g.exitCode ? await identity(h.run, await h.env()) : undefined   // commits land on the user's branches: their own name and email, asked, never made up (ADR 0009)
  if (id?.ok) add(['ok', 'git identity set'])
  else if (id) add(['crit', 'git identity missing: commits need your name and email', 'ask for them, then git config --global user.name and user.email'])
  const b = await r([cfg.store.bin, 'version']), bv = ver(text(b)); facts.bd = bv
  const rev = b?.exitCode === 0 && /--if-revision/.test(text(await r([cfg.store.bin, 'update', '--help'])))
  if (b && !b.exitCode && bv && atLeast(bv, '1.3.0')) add(['ok', `bd ${bv} (${rev ? 'if-revision supported' : 'no if-revision: read-check-write fallback'})`])
  else {
    const head = b && !b.exitCode && bv ? `bd ${bv} is older than 1.3.0` : `${cfg.store.bin} not found`, where = await out(['sh', '-c', 'command -v "$0"', cfg.store.bin])
    const npm = (await r(['npm', '--version']))?.exitCode === 0, pre = npm ? await out(['npm', 'prefix', '-g']) : '', alt = pre && `${pre}/bin/${cfg.store.bin}`, av = alt && alt !== where ? ver(text(await r([alt, 'version']))) : ''
    const mine = !!where && where.startsWith(`${await h.home()}/`)   // a stale bd in a folder the user owns: reversible move, never rm; in a system folder only the human can
    if (where && av && atLeast(av, '1.3.0') && !bv) add(['crit', `bd at ${where} (not beads) shadows bd ${av} at ${alt}`, `restart Claude Code from a shell whose PATH has ${pre}/bin before ${where.slice(0, where.lastIndexOf('/'))}`])   // another product's bd (Bitdefender's, live 0.12.0): never removed
    else if (where && av && atLeast(av, '1.3.0')) add(['crit', `bd ${bv} at ${where} shadows bd ${av} at ${alt}`, mine ? `mv ${where} ${where}.cadre-old` : fix('rm-bd', `removes the old bd at ${where} that shadows bd ${av} at ${alt}. Alternative without sudo: put ${pre}/bin first in PATH.`, `rm ${where}`)])
    else if (npm) add(['crit', head, `npm install -g @beads/bd@latest${mine && bv && where !== alt ? `, then mv ${where} ${where}.cadre-old` : ''}`])
    else if ((await r(['curl', '--version']))?.exitCode === 0) add(['crit', head, BD_SH])
    else add(['crit', head, 'install Node.js (npm) or curl first'])
  }
  if (mac) { facts.jail = 'none'; add(['warn', 'no bwrap on macOS: throwaway-worktree mode, network unenforced']) }
  else {
    const w = await r(['bwrap', '--version']), wv = ver(text(w)); facts.bwrap = wv; facts.jail = await jailMode(h.run)
    if (!w || w.exitCode) add(['crit', 'bwrap not found: checks run unjailed', fix('bwrap', 'installs bubblewrap and socat (Claude Code needs them to run commands safely).', `${pm} bubblewrap socat`, !mac)])
    else if (facts.jail === 'none') {
      const apparmor = (await h.readText('/proc/sys/kernel/apparmor_restrict_unprivileged_userns'))?.trim(), clone = (await h.readText('/proc/sys/kernel/unprivileged_userns_clone'))?.trim()
      if (apparmor === '1') {
        const bin = (await out(['sh', '-c', 'command -v bwrap'])) || '/usr/bin/bwrap'
        add(['warn', `bwrap ${wv} is blocked by AppArmor (kernel.apparmor_restrict_unprivileged_userns=1)`, fix('bwrap-apparmor', `lets only bwrap create user namespaces (AppArmor blocks it: kernel.apparmor_restrict_unprivileged_userns=1). The safest fix.`, `printf 'abi <abi/4.0>,\\ninclude <tunables/global>\\nprofile bwrap ${bin} flags=(unconfined) {\\n  userns,\\n  include if exists <local/bwrap>\\n}\\n' | tee /etc/apparmor.d/bwrap >/dev/null\nsystemctl reload apparmor`)])
        scripts.push({ path: `${dir}/README`, text: `cadre setup: less safe alternatives to ${shown}/bwrap-apparmor.sh\nThey allow user namespaces for EVERY program (Claude Code's sandbox included). Run as root, one of:\n\n  sysctl -w kernel.apparmor_restrict_unprivileged_userns=0   # until reboot\n  echo 'kernel.apparmor_restrict_unprivileged_userns=0' | tee /etc/sysctl.d/60-userns.conf   # keeps it across reboots\n` })
      } else if (clone === '0') add(['warn', `bwrap ${wv} cannot create a user namespace (kernel.unprivileged_userns_clone=0)`, fix('userns-clone', 'allows unprivileged user namespaces (kernel.unprivileged_userns_clone=0 blocks bwrap).', 'sysctl -w kernel.unprivileged_userns_clone=1')])
      else add(['warn', `bwrap ${wv} cannot create a user namespace`, 'see https://code.claude.com/docs/en/sandboxing'])
    } else add(facts.jail === 'copy' ? ['ok', `bwrap ${wv}: copy jail (overlay needs >= 0.11; works, a little slower)`] : ['ok', `bwrap ${wv}: overlay jail`])
    const s = await r(['socat', '-V'])
    add(!s || s.exitCode ? ['crit', 'socat not found (Claude Code needs it on Linux)', fix('socat', 'installs socat (Claude Code needs it on Linux).', `${pm} socat`, !mac)] : ['ok', 'socat present'])
  }
  const root = await wtRootOf(h, cfg); let p = root   // read-only: the nearest existing ancestor must be writable
  while (p.length > 1 && !(await h.stat(p))) p = p.slice(0, p.lastIndexOf('/')) || '/'
  if ((await r(['test', '-w', p]))?.exitCode === 0) add(['ok', `${mac ? 'macOS' : 'Linux'}; worktree root ${root} is writable`])
  else add(['crit', `worktree root ${root} is not writable`, `set worktrees.root in ~/.claude/cadre.json, or fix the permissions of ${p}`])
  return { rows, facts, scripts }
}
// setup only (doctor stays read-only). Returns path -> reason for every script that could not be written
const put = async (h: Host, ss: Script[]): Promise<Map<string, string>> => {
  const bad = new Map<string, string>()
  for (const s of ss) { try { await h.write(s.path, s.text); if (s.exec && (await h.run(['chmod', '700', s.path])).exitCode) throw new Error('chmod failed') } catch (e) { bad.set(s.path, (e as Error).message.split('\n')[0].slice(0, 60)) } }
  return bad
}

// ---- report: one line to the model; the rows go to the pane and ONE summary line to the log (never a multi-line string: the transcript shows it as U+FFFD) ----
async function report(h: Host, name: string, rows: Row[], open = true): Promise<string> {
  await h.ui.update(u => ({ ...u, 'doctor.rows': rows }))
  const bad = rows.filter(r => r[0] === 'crit').length, warn = rows.filter(r => r[0] === 'warn').length
  const line = `${name}: ${[bad && `${bad} fail`, warn && `${warn} warn`, !bad && !warn && 'all ok', 'see the cadre pane'].filter(Boolean).join(' · ')}`
  let fresh = false; await h.ui.update(u => { fresh = u['doctor.last'] !== line; return { ...u, 'doctor.last': line } })
  if (fresh) h.log(line)   // a re-check with the same result adds no new transcript row
  if (h.ops && open) await openPane(h, 'doctor')
  return bad || warn ? `${name}: ${bad} fail, ${warn} warn — report in the cadre pane` : `${name}: all ok`
}

// ---- setup's checklist (commands/agentrun re-runs it at every main turn end): the machine rows plus the user settings; fix scripts for sudo are written here.
// No crit row left = done, and the stamp is written. Warn rows never block.
export async function setupItems(h: Host): Promise<Item[]> {
  const m = await machine(h, await cfgOf(h)), bad = await put(h, m.scripts), path = `${await h.home()}/.claude/settings.json`
  for (const x of m.scripts) if (bad.has(x.path) && x.run) {   // no path to a missing file: a note, the whole command in ONE log line
    for (const r of m.rows) if (r[2] === `! ${x.run}`) r[2] = `couldn't write the fix script (${bad.get(x.path)}); the exact command is in the cadre log`
    h.log(`fix command: ${x.full}`)
  }
  const p = await mplan(h, path, PATCH).catch((e: Error) => e), need = !(p instanceof Error) && p.lines.length > 0
  m.rows.push(p instanceof Error ? ['crit', `user settings unreadable: ${p.message}`] : need ? ['crit', 'user settings lack env CLAUDE_CODE_ENABLE_TODO_TOOLS="1"', 'confirm the user settings: press 1'] : ['ok', 'user settings: env CLAUDE_CODE_ENABLE_TODO_TOOLS is set'])
  await report(h, 'setup', m.rows, false)   // the run card holds the checklist; the pane's doctor tab has the rows
  if (!m.rows.some(r => r[0] === 'crit')) await h.store.set(STAMP, { cc: m.facts.cc, bd: m.facts.bd, bwrap: m.facts.bwrap ?? '', jail: m.facts.jail, at: await h.now() })
  if (need) await proposeUser(h, p.lines, fnv1a64(p.lines.join('\n') + (p.old ?? '')))
  const home = await h.home()
  return [...m.rows.map(([l, t, f]) => ({ name: t.replaceAll(`${home}/`, '~/'), st: need && /^user settings lack/.test(t) ? 'wait' : l === 'crit' ? 'fail' : l === 'warn' ? 'warn' : 'ok', why: l === 'ok' ? undefined : f?.replace(/^! /, '').replaceAll(`${home}/`, '~/') })), await prefsItem(h)]
}
// The user settings are never edited by a model (ADR 0010): cadre shows the merge on a card (init:91) and writes it after Confirm (.bak, re-read), like init's safety settings.
async function proposeUser(h: Host, lines: string[], sig: string): Promise<void> {
  if ((await h.ui.read())['setup.pending'] === sig && (await h.board.read()).decisions?.some(d => d.id === `init:${USER_CARD}`)) return
  await h.ui.update(u => ({ ...u, 'setup.pending': sig }))
  await initPropose(h, USER_CARD, `setup user settings\n${sig}`, { title: 'setup · user settings · confirm', short: 'setup user settings', sub: 'setup', lines: ['cadre writes this after you confirm (a .bak is kept):', ...lines.map(l => `  ~/.claude/settings.json: ${l}`)] })
}
// An older repo keeps its task store in .beads. Moving it is never automatic: doctor shows a card (init:92); its Confirm (`setup confirm`) lands here.
async function proposeMove(h: Host): Promise<void> {
  if ((await h.board.read()).decisions?.some(d => d.id === `init:${STORE_CARD}`)) return
  await initPropose(h, STORE_CARD, 'move task store', { title: 'task store · move to .cadre/store · confirm', short: 'move task store', sub: 'setup', lines: ['the task store is in .beads; cadre moves it to .cadre/store after you confirm.', 'No task may be running. If the store does not answer from its new place, it goes back.', 'By hand afterwards: BEADS_DIR=.cadre/store bd list'] })
}
async function moveStoreNow(h: Host): Promise<string> {
  const root = await h.cwd(), cfg = await cfgOf(h)
  return `setup: ${await moveStore(h, root, dir => new BdStore({ run: h.run, cwd: root, actor: 'cadre/setup', bin: cfg.store.bin, timeoutMs: cfg.store.timeoutMs, dir }))}`
}
export async function confirmUser(h: Host): Promise<string> {
  if ((await h.board.read()).decisions?.some(d => d.id === `init:${STORE_CARD}`)) { await initConfirm(h, STORE_CARD); return moveStoreNow(h) }
  const was = (await h.ui.read())['setup.pending'], good = await initConfirm(h, USER_CARD), path = `${await h.home()}/.claude/settings.json`
  if (!good || !was) return 'setup: nothing pending; press 1 for the current diff'
  const p = await mplan(h, path, PATCH); if (fnv1a64(p.lines.join('\n') + (p.old ?? '')) !== was) return 'setup: the settings file changed since you saw it; nothing written'
  await mapply({ readText: h.readText, writeText: h.write }, path, PATCH); await h.ui.update(({ 'setup.pending': _p, ...u }) => u)
  return 'setup: user settings written'
}
// session.start: no stamp, or the Claude Code build changed since: one toast
export async function nudge(h: Host): Promise<void> {
  const s = (await h.store.get(STAMP)) as { cc?: string } | undefined, cc = await h.version?.().catch(() => undefined)
  if (!s || (cc && s.cc !== cc)) h.toast('cadre: run /cadre setup')
}

// ---- doctor: machine rows + project rows; no writes ----
async function project(h: Host, cfg: Config): Promise<Row[]> {
  const root = await h.cwd(), rows: Row[] = [], safe = async <T>(f: () => Promise<T>, d: T) => f().catch(() => d)
  if (!(await h.secret.read()).active && !(await h.readText(`${root}/.cadre/config.json`))) return [['warn', 'project: not set up here (no .cadre/config.json)', '/cadre <goal> sets it up']]
  if (!(await gitOk(h.run, root, ['rev-parse', '--git-dir']))) return [['crit', 'not inside a git repo', '/cadre init']]
  const miss = (await progress(h)).filter(s => !s.done)
  rows.push(miss.length ? ['warn', `init incomplete: ${miss.map(s => s.name).join(', ')}`, '/cadre init'] : ['ok', 'init complete'])
  if ((await h.store.get(await scoped(h, 'gitignore.review'))) && (await h.readText(`${root}/.gitignore`))?.includes(BD_BLOCK.split('\n')[0])) rows.push(['warn', 'bd added ignore lines to .gitignore; review them', 'keep or remove the "# Beads / Dolt files" block'])   // left alone: the file changed during setup (commands/init.restoreIgnore)
  const pol = await policyOf(h), c = assess(await safe(() => h.settings(), {}), pol.repo, pol.wtRoot)
  rows.push(c.state === 'contained' ? ['ok', 'containment contained'] : ['warn', `containment degraded: ${c.why.join('; ')}`, '/cadre init'])
  const dir = await dirOf(h, root)
  rows.push(dir ? ['ok', 'task store: .cadre/store (by hand: BEADS_DIR=.cadre/store bd list)'] : ['warn', 'task store: .beads (older layout; by hand: bd list)', 'press 1: move it to .cadre/store in the dialog'])
  if (!dir) await proposeMove(h)
  let tasks: Awaited<ReturnType<Awaited<ReturnType<typeof storeOf>>['list']>> = []
  try { const s = await storeOf(h), p = await s.probe(); rows.push(!p.ok ? ['crit', `beads: ${p.detail.slice(0, 100)}`, '/cadre init'] : p.journal ? ['ok', `beads ${p.version} reachable, journal on`] : ['warn', 'beads reachable, journal off', '/cadre init']); if (p.ok) tasks = await s.list({}) }
  catch (e) { rows.push(['crit', `beads unreachable: ${(e as Error).message.slice(0, 100)}`, '/cadre init']) }
  if (await oldState(h, tasks)) rows.push(['warn', 'finish or cancel plans from the previous version before upgrading', 'its run state is not read: finish or cancel those plans with the previous version'])
  for (const b of [cfg.branches.main, cfg.branches.dev]) rows.push(b && await exists(h.run, root, b) ? ['ok', `branch ${b} exists`] : ['crit', `branch ${b || '(main unset)'} missing`, '/cadre init'])
  const now = await h.now(), stale = tasks.filter(t => t.assignee && ['active', 'review', 'blocked'].includes(t.category) && !leaseLive(t, now)).map(t => t.id), bound = Object.keys(await h.bind.read()).filter(k => !k.startsWith('~')).length
  rows.push(stale.length ? ['warn', `expired leases: ${stale.join(', ')}`, 'main spawns them again; they rebind'] : ['ok', `no stale leases; ${bound} agent(s) bound`])
  const b = await h.board.read(), fl = b.tasks.filter(t => t.flags.length)
  rows.push(fl.length ? ['warn', `open flags: ${fl.map(t => `${t.id} ${t.flags.join('+')}`).join(', ')}`, 'press 1: answer it in the dialog'] : ['ok', 'no open flags'])
  const q = (await h.run(['git', '-C', root, 'for-each-ref', 'refs/cadre/quarantine', '--format=%(refname)'])).stdout.split('\n').filter(Boolean).length
  rows.push(q ? ['warn', `${q} quarantined ref(s)`, 'press 1: keep or restore in the dialog'] : ['ok', 'no quarantined refs'])
  const rq = ((await h.store.get(await qk(h))) as unknown[] | undefined)?.length ?? 0
  rows.push(rq ? ['warn', `${rq} resume(s) queued`, 'they are sent at the next turn'] : ['ok', 'no queued resumes'])
  for (const [t, v] of Object.entries(cfg.sync)) {
    const a = (cfg.adapters as Record<string, any>)[(v as any)?.adapter ?? t]
    rows.push(await call(h, t, a ?? {}, 'ping', {}, 5000).then((): Row => ['ok', `sync ${t} answers`], (e): Row => ['warn', `sync ${t}: ${e.message}`, '/cadre sync now']))
  }
  rows.push(b.drive.stopped ? ['warn', `drive stopped: ${b.drive.stopped}`, 'press 0 on the band to resume'] : b.drive.paused ? ['warn', `drive paused: ${b.drive.paused}`, 'it continues by itself after you answer'] : ['ok', `drive ${b.drive.on ? `on, ${b.drive.turns} turns` : 'off until a plan is approved'}`])
  return rows
}
// clean break (0.14): what 0.13 kept is not read: its counters on open tasks, hand-back marks, agents bound with no run record (they started from a TASK-<id> prompt)
export async function oldState(h: Host, tasks: { category: string; meta: Record<string, string> }[]): Promise<boolean> {
  const bind = await h.bind.read(), keys = ['attempts', 'testerRounds', 'rework', 'rebase', 'nudge'].map(k => `cadre.${k}`)   // read only: the write scan (scripts/budget.mjs) matches these names
  if (tasks.some(t => ['active', 'review', 'blocked'].includes(t.category) && keys.some(k => t.meta[k])) || 'handed' in (await h.ui.read())) return true
  for (const a of Object.keys(bind)) if (!a.startsWith('~') && !(await runOf(h, a))) return true
  return false
}
export async function doctor(h: Host): Promise<string> {
  const cfg = await cfgOf(h)
  const m = await machine(h, cfg)   // read-only: a fix line only when its script already exists (setup writes them)
  for (const x of m.scripts) if (x.run && (await h.readText(x.path)) === null) for (const r of m.rows) if (r[2] === `! ${x.run}`) r[2] = 'run /cadre setup to prepare the fix'
  const pe = (await h.ui.read()).paneErr as { reason: string } | undefined   // ui/index.openPane: the last open that failed this session
  return report(h, 'doctor', [...m.rows, await prefsRow(h), ...(await doctorRows(h)), ...(pe ? [['warn', `the cadre pane could not open: ${pe.reason}`, 'run /cadre to open it; if it keeps failing, report the reason'] as Row] : []), ...(await project(h, cfg))])
}

files.commands/agentrun.ts:
// Agent-run setup and init (ADR 0010). `/cadre setup|init` hands MAIN one short brief that points at a guide; Claude does the work with visible tool calls under a
// scoped maintenance lease (policy/guards). cadre only CHECKS: at every main turn end while a run is active it re-runs the checks, redraws the checklist decision and,
// when something Claude owns still fails, sends ONE follow-up naming it (at most 3 per run; then the decision shows what is left and Retry).
import { modelText } from '../core/say'
import type { Host, Secret } from '../types'
import { fnv1a64 } from '../core/board'
import { ask, settle } from '../core/decide'
import { initItems, restoreIgnore, scoped, type Item } from './init'
import { setupItems } from './doctor'
import { LIMIT } from '../policy/guards'
import { RUN } from '../core/dispatch'
import { goal as goalBrief, queueBrief, sendBrief } from '../core/lanes'
import { storeOf } from '../core/dispatch'
import { diff as jdiff } from '../policy/settings'
import { EXPLORE } from '../core/clarify'

type Kind = 'setup' | 'init'
const G: Record<Item['st'], string> = { ok: '✓', fail: '✗', wait: '…', todo: '·', warn: '!' }
const items = (h: Host, k: Kind, quick = false) => (k === 'setup' ? setupItems(h) : initItems(h, { quick }))
const finished = (its: Item[]) => its.every(i => i.st === 'ok' || i.st === 'warn')
const WHAT = { setup: 'Set up cadre on this machine', init: 'Set up cadre in this project' }

const end = async (h: Host, done = false) => { if (done) { await h.store.del(await scoped(h, 'run')); await h.ui.update(({ halt: _x, ...u }) => u) } await h.secret.update(({ run: _r, ...s }) => s) }   // done: finished or cancelled; a stopped run stays open (halted)
// a run started here and never finished (Claude Code quit or was killed mid-run, or it stopped): kept in $.store, as session memory goes with the session. None while a run is on.
type Halt = { kind: Kind; goal?: { text: string; mode: 'auto' | 'yolo' }; follow?: number }   // follow: the stop refusals spent (a resume after /clear keeps them)
const mark = async (h: Host, r: Halt) => h.store.set(await scoped(h, 'run'), r)
export const halted = async (h: Host) => ((await h.secret.read()).run ? undefined : ((await h.store.get(await scoped(h, 'run'))) as Halt | undefined))
export const haltText = (r: Halt) => `Setup was interrupted · /cadre ${r.goal ? r.goal.text.slice(0, 80) : r.kind === 'setup' ? 'setup' : '<goal>'} to pick it up`
export async function halt(h: Host): Promise<void> { const r = await halted(h); if (r) await h.ui.update(u => ({ ...u, halt: haltText(r) })) }   // session.start: the band says it (ui/v2/band)
// $.prompt.submit is refused from a command or a press frame, and $.clock.after inherits that frame (live, 0.7.0). So a brief waits in the run (`brief`)
// and goes out from main's turn end or the session's 5 s timer (pump); it starts once the session is idle.
const send = (h: Host, brief: string) => h.secret.update(s => (s.run ? { ...s, run: { ...s.run, brief } } : s))
// Claude Code 2.1.299: after the human stops Claude (Esc) a plugin's submit resolves { drop } until the human sends input; only a submit from a press's own frame
// goes, and a dialog answer's work runs later (quick tier user2: every retry refused again, 37 dialogs). So a drop holds the run: ONE dialog says to type anything
// in the prompt, nothing is submitted while held (no retry storm), and the human's typed line (resume, from prompt.submit) restarts it; the timer sends the step.
// inFrame: the retry of a stop that was not a drop (the limits); refused there, it waits for the timer.
export async function pump(h: Host, inFrame = false): Promise<void> {
  if ((await h.ui.read()).held) return
  let text: string | undefined; await h.secret.update(s => { text = s.run?.brief; return text ? { ...s, run: { ...s.run!, brief: undefined } } : s })
  const r = text ? await h.submit?.(modelText('brief', text)).catch((e: Error) => ({ err: e.message })) as { drop?: string; err?: string } | undefined : undefined
  if (r?.drop || r?.err) h.log(`could not hand the step to Claude: ${(r.drop ?? r.err)!.slice(0, 120)}`)
  const errs = r?.err ? ((await h.secret.read()).run?.errs ?? 0) + 1 : 0   // a thrown submit is no human stop: the step goes again on the next tick, held after 3 (a host error that repeats must not loop silently)
  if (errs && errs < 3) { await h.secret.update(s => (s.run ? { ...s, run: { ...s.run, errs } } : s)); return send(h, text!) }
  if (r?.drop && inFrame) return send(h, text!)
  const run = (r?.drop || r?.err) && (await h.secret.read()).run
  if (run) { await h.ui.update(u => ({ ...u, shown: [...((u.shown as string[] | undefined) ?? []), `run:${run.kind}`] })); await stuck(h, run, await items(h, run.kind), 'Claude was stopped before it got the next step.', true) }
  if (!inFrame && !(await h.secret.read()).run) await sendBrief(h)   // a `/cadre <goal>` brief (core/lanes); a run's own step goes first, the goal after it ends
}
// the human typed in the prompt (prompt.submit, composer): a held run starts again, its step goes on the next tick (pump)
// Only a held card's run restarts (never an older stopped card on another hold), and it does so even when ui was reset (/clear): kind from the card, goal from the halt.
const HELD = ' stopped · type anything to go on'
export async function resume(h: Host): Promise<void> {
  const u = await h.ui.read(); if (u.held) await h.ui.update(({ held: _h, ...x }) => x)
  if ((await h.secret.read()).run) return
  const d = (await h.board.read()).decisions?.find(x => x.id.startsWith('run:') && x.title.endsWith(HELD)); if (!d) return
  const k = d.id.slice(4) as Kind, rt = u.retry as { kind: Kind; goal?: Halt['goal']; follow?: number } | undefined
  const r = rt?.kind === k ? rt : (await halted(h)) ?? {}
  await settle(h, d.id); await start(h, k, r.goal, r.follow ?? 0)
}

async function draw(h: Host, k: Kind, its: Item[], state: 'on' | 'stopped' | 'held' | 'done', note?: string): Promise<void> {
  const n = its.filter(i => i.st === 'ok' || i.st === 'warn').length, human = !its.some(i => i.st === 'fail') && its.some(i => i.st === 'wait')
  const title = state === 'done' ? `${k} · all done` : state === 'held' ? `${k}${HELD}` : state === 'stopped' ? `${k} · Claude stopped · ${its.length - n} left` : `${k} · ${n}/${its.length} done · ${human ? 'needs you' : 'Claude is on it'}`
  const lines = [...(note ? note.split('\n') : []), ...its.map(i => `${G[i.st]} ${i.name}${i.why ? `: ${i.why}` : ''}`)]
  await ask(h, { id: `run:${k}`, kind: 'init', title, short: title, lines, hash: fnv1a64(title + lines.join('\n')), tab: 'epic', ...(state === 'done' || (state === 'on' && (!human || (await h.secret.read()).run?.goal)) ? { quiet: true as const } : {}),   // done: shown in the pane, never a "needs you"   // a goal run: the human's cards (safety, then mission + plan) pop themselves; the checklist never does
    options: state === 'stopped' ? [{ key: 'r', label: 'Let Claude try again', verb: 'change', run: `${k} retry` }, { key: 'x', label: `Stop ${k === 'init' ? 'setup' : k}`, verb: 'reject', run: `${k} cancel` }]
      : state === 'held' ? [{ key: 'x', label: `Stop ${k === 'init' ? 'setup' : k}`, verb: 'reject', run: `${k} cancel` }]   // no retry here: an answer cannot hand the step over (pump)
      : [{ key: 'x', label: state === 'done' ? 'Close' : 'Cancel', verb: 'reject', run: `${k} cancel` }] })
}
// where in the guide each check is done (guides/init.md phases)
const PHASE: Record<string, string> = { repository: 'phase 1', 'task store': 'phase 2', mission: 'phase 3', 'build and test commands': 'phase 4', 'commands pass on a clean checkout': 'phase 4', workflow: 'phase 4', changelog: 'phase 5' }
const redList = (fails: Item[]) => fails.map((i, n) => `${n + 1}. ${i.name}${i.why ? `: ${i.why}` : ''}${PHASE[i.name] ? ` (${PHASE[i.name]})` : ''}`)
const followUp = async (h: Host, k: Kind, fails: Item[], guide: string) => [
  'Setup is not done: these checks still fail.', ...redList(fails),
  `Fix them now, following ${guide}. If you cannot fix one, say which one and why, then stop.`,
].join('\n').replaceAll(`${await h.home()}/`, '~/')
// Claude stopped with checks still red and cannot go on (refused 3 times, or it stopped without trying again): ONE dialog for the human, never a silent "running"
async function stuck(h: Host, r: NonNullable<Secret['run']>, its: Item[], why: string, held = false): Promise<string> {
  await end(h); await mark(h, { kind: r.kind, ...(r.goal ? { goal: r.goal } : {}), follow: r.follow }); await h.ui.update(u => ({ ...u, retry: { kind: r.kind, goal: r.goal, follow: r.follow }, ...(held ? { held: true } : {}) }))   // "Let Claude try again" starts the same run, the goal still queued and its stop refusals spent (live 0.12.0: 29 retries, each refilled)
  const said = (r.said ?? '').replace(/\s+/g, ' ').trim()
  await draw(h, r.kind, its, held ? 'held' : 'stopped', [why, ...(held ? ['Type anything in the prompt (for example: go on) and Claude picks up the next step.'] : []), ...(said ? [`Claude: "${said.slice(0, 200)}${said.length > 200 ? '…' : ''}"`] : [])].join('\n'))
  return `${r.kind}: stopped · press 1`
}

// `/cadre setup` | `/cadre init` (human origin only: core/dispatch). Nothing open: done at once. Else the lease starts and main gets the brief.
// `goal` (the onboarding dialog's Set up, commands/cadre): init skips the mission question (drafted with the plan) and the goal flow follows once every check passes (ADR 0014)
// again: the human's "Let Claude try again" (the stopped run's refusal count): ONE stop budget per run, a retry never refills it, and the brief says the user asked
// (live 0.12.0: an Esc on a write told Claude to wait for the user; it read every retry brief as the plugin's, not the user's, and stopped again)
export async function start(h: Host, k: Kind, goal?: { text: string; mode: 'auto' | 'yolo' }, again?: number): Promise<string> {
  if (goal) await settle(h, 'init:goal')
  await h.ui.update(({ held: _h, ...u }) => u)   // a new start hands its brief over: a hold left by an earlier stop must not swallow it (pump re-holds once if the host still drops)
  const at = await h.now(); await h.secret.update(s => ({ ...s, run: { kind: k, at, turns: 0, follow: again ?? 0, guide: '', snap: {}, ...(goal ? { goal } : {}) } }))   // before the checks: mission waits for the plan in a goal run
  const its = await items(h, k)
  if (finished(its)) { await end(h, true); await settle(h, `run:${k}`); if (goal) { await goalBrief(h, goal.text, goal.mode); return `${k}: all done · ${goal.mode === 'yolo' ? 'yolo · ' : ''}Claude plans your goal` } return `${k}: all done` }
  const guide = `${(await h.root?.()) ?? '.'}/guides/${k}.md`; await mark(h, { kind: k, ...(goal ? { goal } : {}) })
  const gi = k === 'init' && its.find(i => i.name === 'task store')?.st !== 'ok' ? await h.readText(`${await h.cwd()}/.gitignore`) : undefined   // this run will init the task store: keep the .gitignore bytes (init.restoreIgnore)
  await h.secret.update(s => (s.run ? { ...s, run: { ...s.run, guide, ...(gi !== undefined ? { gi: { had: gi !== null, text: gi ?? '' } } : {}) } } : s)); await resnap(h)
  await draw(h, k, its, 'on')
  const at0 = k === 'init' ? ` The project root is ${await h.cwd()}: start every Bash call with cd "${await h.cwd()}" && and give files there by their full path.` : ''   // a shell left in a package folder made a second .cadre there, live 0.10.0
  const who = again === undefined ? '' : 'The user asked you to go on: do it now. '
  await send(h, who + (goal ? `${WHAT[k]}, then plan the user's goal (it comes next). Follow ${guide} step by step.${at0} Skip the mission question: you draft the mission together with the plan.` : `${WHAT[k]}. Follow ${guide} step by step.${at0}`))
  return `${k}: Claude is on it · progress in the cadre pane${goal ? ' · then your goal' : ''}`
}
// re-check now (a main turn ended, or the human answered a gate in the dialog): done ends the run; a failure Claude owns gets a follow-up; the limits stop it
export async function recheck(h: Host, turn = false, ended = turn): Promise<string> {   // ended: Claude stopped (its turn end, or the watchdog); a human answer only re-checks
  const r = (await h.secret.read()).run; if (!r) return ''
  if (await moved(h, r)) return `${r.kind}: stopped · a settings file changed · press 1`
  const k = r.kind, its = await items(h, k), fails = its.filter(i => i.st === 'fail'), turns = r.turns + (turn ? 1 : 0)
  if (finished(its)) await restoreIgnore(h)
  if (finished(its) && r.goal) { await end(h, true); await settle(h, `run:${k}`); await goalBrief(h, r.goal.text, r.goal.mode); h.toast('init done · Claude plans your goal'); return `${k}: all done · Claude plans your goal` }   // no "all done" dialog: the plan's dialog is next
  if (finished(its)) { await end(h, true); await draw(h, k, its, 'done'); h.toast(`cadre: ${k} done`); return `${k}: all done` }
  const out = turns >= LIMIT.turns || (await h.now()) - r.at >= LIMIT.ms
  if (out) return stuck(h, r, its, 'the time or turn limit was reached')
  if (fails.length && ended && (r.follow >= LIMIT.follow || r.stopSeen)) return stuck(h, r, its, r.follow >= LIMIT.follow ? 'Claude stopped 3 times with checks still failing' : 'Claude stopped with checks still failing')   // stopSeen: the stop check let it stop (it said it cannot go on)
  await h.secret.update(s => (s.run ? { ...s, run: { ...s.run, turns, follow: s.run.follow + (fails.length && ended ? 1 : 0) } } : s))
  await draw(h, k, its, 'on')
  if (fails.length && ended) await send(h, await followUp(h, k, fails, r.guide))   // Claude is still at work otherwise: its stop is checked when it comes
  if (turn) await pump(h)
  return `${k}: ${fails.length ? 'Claude is on it' : 'waiting for you · press 1'}`
}
// main's turn.complete (register.ts): works in dormant repos too
export async function turnEnd(h: Host, e: { agentId?: string; answer?: string }): Promise<void> {
  if (e.agentId) return
  if (!(await h.secret.read()).run) { const now = await h.now(); await h.secret.update(s => (s.goalRun?.on ? { ...s, goalRun: { ...s.goalRun, busy: false, seen: now } } : s)); return }   // a goal run: the watchdog's clock
  const now = await h.now(); await h.secret.update(s => (s.run ? { ...s, run: { ...s.run, busy: false, seen: now, ...(e.answer ? { said: e.answer } : {}) } } : s))
  await recheck(h, true)
}
// main's turn.start / tool.call (register.ts): the watchdog's clock, and the tool count the stop check reads
export async function seen(h: Host, o: { start?: boolean; tool?: boolean; name?: string; type?: string } = {}): Promise<void> {   // name: main's tool, before it runs (a goal run); type: an Agent call's subagent_type
  const s0 = await h.secret.read(); if (!s0.run && !s0.goalRun?.on) return
  const now = await h.now(), busy = o.start ? { busy: true } : {}
  await h.secret.update(s => (s.run ? { ...s, run: { ...s.run, seen: now, ...busy, ...(o.tool ? { tools: (s.run.tools ?? 0) + 1 } : {}) } }
    : s.goalRun?.on ? { ...s, goalRun: { ...s.goalRun, seen: now, ...busy, ...(o.name ? { last: o.name, ...(o.name === 'Agent' || o.name === 'Task' ? (o.type === EXPLORE ? { explored: true } : { spawned: true }) : {}) } : {}) } } : s))   // the clarify explorer (ADR 0020) is not the ask step: a goal that only explored still owes its plan
}

// ---- Claude's stop during a run (classic Stop): while a check Claude owns is red, the stop is refused with the list (at most 3 per run). A second stop with no tool
// call since the last refusal is Claude saying it cannot go on: it may stop, and its turn end shows the human the dialog. Where classic hooks are off (managed
// machines) this never runs and the turn end sends the same list as a follow-up instead. ----
export async function stopCheck(h: Host, e: { last_assistant_message?: string }): Promise<string | null> {
  const r = (await h.secret.read()).run; if (!r) return goalStop(h)
  const fails = (await items(h, r.kind)).filter(i => i.st === 'fail')
  await h.secret.update(s => (s.run ? { ...s, run: { ...s.run, stopSeen: true, ...(e.last_assistant_message ? { said: e.last_assistant_message } : {}) } } : s))
  if (!fails.length || r.follow >= LIMIT.follow || (r.follow > 0 && !r.tools)) return null
  await h.secret.update(s => (s.run ? { ...s, run: { ...s.run, follow: s.run.follow + 1, tools: 0 } } : s))
  return followUp(h, r.kind, fails, r.guide)
}
// ---- after each of main's tool calls in a run: one line naming what is still red (no clean-checkout run, no proposal) ----
export async function redNote(h: Host): Promise<string | null> {
  const r = (await h.secret.read()).run; if (!r) return null
  const fails = (await items(h, r.kind, true)).filter(i => i.st === 'fail')
  const root = await h.cwd(), sh = await h.shell?.().catch(() => undefined), at = sh && sh !== root ? ` · your shell is in ${sh}; the project root is ${root}` : ''
  return fails.length ? `setup still open: ${fails.map(i => `${i.name}${i.why ? ` (${i.why})` : ''}`).join('; ')}${at}`.replaceAll(`${await h.home()}/`, '~/') : null
}
// ---- the watchdog (the 5 s tick): a run whose main has been quiet for a while is checked as if Claude had stopped. A missed turn end (live: a run sat in "running"
// with nothing working) still ends in a follow-up or the dialog. Quiet = no turn on for 60 s, or a turn on with no step or tool call for 10 minutes. ----
export const QUIET = { idle: 60_000, busy: 600_000 }
export async function watch(h: Host): Promise<void> {
  const sc = await h.secret.read(), r = sc.run ?? sc.goalRun
  if (sc.run?.brief && (await h.now()) - sc.run.at >= LIMIT.ms) return void (await recheck(h))   // a brief that never goes out: the time limit still stops the run
  if (!r || (sc.run ? sc.run.brief : !sc.goalRun?.on || (await h.ui.read()).goal)) return   // a brief waiting goes out first (pump)
  const since = (await h.now()) - (r.seen ?? (sc.run?.at ?? 0))
  if (since < (r.busy ? QUIET.busy : QUIET.idle)) return
  if (((await h.board.read()).decisions ?? []).some(d => !d.quiet)) return   // the human has something to answer: that is not a stall
  if (!sc.run) { await h.secret.update(s => (s.goalRun ? { ...s, goalRun: { ...s.goalRun, busy: false } } : s)); await seen(h); const t = await goalStop(h); if (t) await queueBrief(h, t); return }   // a goal run: the refusal goes as the next brief
  await h.secret.update(s => (s.run ? { ...s, run: { ...s.run, busy: false } } : s)); await seen(h)
  await recheck(h, false, true)
}

// ---- a goal run (core/lanes.goal): main's stop is refused while its lane's step is not done (ask: no Agent spawned; lite/full: no plan with a task; milestone: no
// roadmap with an epic), at most twice. Live: main chose the lane, said "next is step 2" and stopped, and no plan ever came. A stop right after it asked the
// user a question (AskUserQuestion) goes through. After the second refusal the band says the plan wasn't drafted. ----
export const GOAL_FOLLOW = 2
async function goalMissing(h: Host): Promise<string | null> {
  const p = (await h.board.read()).plan
  if (p && p.slug !== 'mission' && p.state !== 'done-on-dev' && p.state !== 'released') {
    if (p.state !== 'draft' || (await (await storeOf(h)).list({ parent: p.id })).some(t => t.type !== 'gate' && t.category !== 'cancelled')) return null   // drafted, or a plan already open (the goal was refused: main tells the user). The store, any open child: a lite plan's own task counts, and one the approval is turning open while the board still says draft (live: main drafted it again)
    return p.lane === 'milestone' ? `Roadmap ${p.id} has no epics yet: draft them now, one TaskCreate per epic as the roadmap rules say, then tell the user to approve it in the dialog (key 1 opens it) and stop.`
      : `Plan ${p.id} has no tasks yet: draft them now, one TaskCreate per task as the plan rules say, then tell the user to approve it in the dialog (key 1 opens it) and stop.`
  }
  return 'The goal is not planned yet: draft the plan now. TaskCreate with metadata {"kind": "plan", "lane": "<lite|full|milestone>", "reason": "<one line>"} (lite: that one call is the whole plan; full: then one TaskCreate per task; milestone: then one TaskCreate per epic), then tell the user to approve it in the dialog (key 1 opens it) and stop. For a question (ask), spawn one Agent with it instead, then stop.'
}
async function goalStop(h: Host): Promise<string | null> {
  const g = (await h.secret.read()).goalRun; if (!g?.on || g.last === 'AskUserQuestion') return null   // it asked the user: their answer comes next
  if (g.explored && !g.spawned && Object.values(((await h.ui.read()).asks ?? {}) as Record<string, { answer?: string }>).some(a => a.answer === undefined)) return null   // its explorer is still answering: the answer brings the next turn
  const miss = g.spawned ? null : await goalMissing(h)
  const f = miss && g.missed !== miss ? 0 : g.follow   // a new missing step (it moved on: drafted the plan, still no task) gets its own refusals; the clarify step adds a stop point (live: a lazy main spent both on "not planned")
  if (miss && f < GOAL_FOLLOW) { await h.secret.update(s => (s.goalRun ? { ...s, goalRun: { ...s.goalRun, follow: f + 1, missed: miss } } : s)); return miss }
  await h.secret.update(({ goalRun: _g, ...s }) => s)
  if (miss) await h.ui.update(u => ({ ...u, halt: `the plan wasn't drafted · /cadre ${g.text.slice(0, 80)} to try again` }))   // the band (ui/v2/band); the goal's words stay there
