}
// `/cadre setup|init restore|keep` (human only: core/dispatch)
export async function settingsAnswer(h: Host, how: 'restore' | 'keep'): Promise<string> {
  const hold = (await h.secret.read()).hold; if (!hold) return 'nothing to restore'
