// UI entry points wired by hooks/register.ts (UI-DESIGN 5, 7): render hooks (band, pane, result card), press handlers, the decision dialog (ADR 0012), openPane, resume banner, cursor tick.
// The UI reads the human view, the ring and the secret only; render is pure; writes happen in handlers (and a press's own work runs in after(1), UI-14).
import type { Decision, Host } from '../types'
import { band as bandOf } from './band'
import { pane } from './pane'
import { prog, selId } from './v2/facts'
import { ack, onEvent as notifyEvent, syncStatus } from './notify'
import { queueBrief } from '../core/lanes'
import { ROUTES, dispatch } from '../core/dispatch'
import { color, glyph, glyphRole, readCfg } from './tokens'
import { strictOf } from '../config/index'
import { configPress, refreshSettings } from '../config/route'
import { type Acts, S, at, cols, cut, decisions, draw, kindOf, read, t0 } from './model'

export { ack, syncStatus } from './notify'
let lastW = 0   // width of the last pane draw: sizes a timeline step (a resize is a redraw), not state
const later = (h: Host, fn: () => Promise<unknown>) => h.ops?.after(1, () => fn().catch(e => h.toast(`${e}`)))

// Open the pane on a tab (called by /cadre open|approve and by presses). Where nothing draws, the content goes to $.ui.log instead (C3).
const OPEN = { id: 'cadre', title: 'cadre', columns: 120 }
// The open call is the first thing a command or press does: only there does the engine count it as asked (any width); inside after() it is "unasked" (>= 144 columns, live capture ADR 0008)
// /theme can change after session start: the Raster palette follows it (read on every pane open / tab press and on the tick)
async function syncTheme(h: Host): Promise<void> {
  const th = await h.theme?.().catch(() => undefined)
  if (th && readCfg(await h.ui.read()).theme !== th) await h.ui.update(u => ({ ...u, cfg: { ...(u.cfg as object | undefined), theme: th } }))
}
export async function openPane(h: Host, tab: string, o: { focus?: boolean; quiet?: boolean; pre?: ReturnType<NonNullable<Host['ops']>['open']> } = {}): Promise<void> {
  if (tab === 'settings') await refreshSettings(h)
  await syncTheme(h)
  const opened = o.pre ?? h.ops!.open({ ...OPEN, ...(o.focus === false ? {} : { focus: true as const }) })   // `focus: false` is refused by the engine: leave it out
  const v = await read(h)
  await h.ui.update(u => ({ ...u, tab }))
  const r = await Promise.resolve(opened).catch((x: Error) => ({ isPlaced: false, reason: String(x?.message ?? x) }))   // a refused open used to vanish in the callers' catch: say why
  await h.ui.update(u => ({ ...u, paneErr: r.isPlaced ? undefined : { at: v.now, reason: (r.reason ?? 'not placed').slice(0, 120) } }))   // Doctor shows the last failure
  if (!r.isPlaced) {
    if (!o.quiet) { h.toast(`pane not shown${r.reason ? ` · ${r.reason.slice(0, 40)}` : ''}`) }
    if (decisions(v).length) later(h, () => answerDialog(h))   // no pane (VS Code panel, Remote Control) and no band key: the dialog of the oldest decision
  }
  if (!o.quiet) await ack(h)
}
export async function onEvent(h: Host, e: Parameters<typeof notifyEvent>[1]): Promise<void> {
  await notifyEvent(h, e); await autoAsk(h)
  if (readCfg(await h.ui.read()).flash) h.ops?.after(1600, () => h.ops?.invalidate())   // the 1.5 s row flash ends by a redraw (BRAND §9)
}

// A decision pops its dialog by itself at most ONCE, the first time it can, and only over an empty composer with no dialog of ours up (a `quiet` one never does).
// After that only `1` (band or pane) opens it: a dismissal (Esc) never comes back on its own.
export async function autoAsk(h: Host): Promise<void> {
  if (!h.ask || !h.ops) return
  const shown = ((await h.ui.read()).shown as string[] | undefined) ?? [], fresh = decisions(await read(h)).filter(d => !d.quiet && !shown.includes(d.id))
  if (!fresh.length) return
  if (asking || (await h.ops.peek()).trim()) return   // typing or a dialog up: not shown yet, so the next tick (5 s) pops it once the composer is empty; meanwhile `1` still works
  await h.ui.update(u => ({ ...u, shown: [...shown, ...fresh.map(d => d.id)].slice(-100) }))
  later(h, () => answerDialog(h, fresh[0].id))
}

// The ONE way a decision is answered (ADR 0012): the native AskUserQuestion dialog. Fields first, one ask each (keep the value or type a new one); then the
// decision's runnable options (at most 4; "Not now" added when fewer than 2; the engine adds "Type something"). Typed text there is a change request to main
// (Decision.change). The answer goes to core/dispatch.answer, which re-checks the hash; a refusal that moved the decision (stale, an invalid value) re-asks it.
// Dismissed or -p ($.ui.ask rejects): nothing is decided. Auto-answers by other mods are an accepted risk (ADR 0012).
export const NOT_NOW = 'Not now'
const body = (d: Decision) => [d.title, ...(d.error ? [`! ${d.error}`] : []), ...d.lines].slice(0, 7).join('\n')   // the title + at most 6 lines
let asking = false
export async function answerDialog(h: Host, id?: string): Promise<void> {
  if (!h.ask || !h.answer || asking) return
  asking = true
  try {
    for (let n = 0, last = ''; n < 3; n++) {
      const ds = decisions(await read(h)), d = id ? ds.find(x => x.id === id) : ds[0]
      if (!d || d.hash === last) return
      const vals: Record<string, string> = {}
      for (const f of d.fields ?? []) {
        const keep = f.value ? `Keep ${f.value}` : 'Leave it empty', x = (await h.ask(`${f.label}?`, [keep, 'Cancel'])).trim()
        if (x === 'Cancel') return
        vals[f.key] = x === keep ? f.value ?? '' : x
      }
      const os = d.options.filter(o => o.run).slice(0, 4), x = (await h.ask(body(d), [...os.map(o => o.label), ...(os.length < 2 ? [NOT_NOW] : [])])).trim(), o = os.find(y => y.label === x)
      if (!o) {
        if (x && x !== NOT_NOW && !d.fields?.length) { await queueBrief(h, `${d.change ?? `About "${d.title}": `}${x}`); h.log(`sent to Claude · ${cut(x, 60)}`) }
        return
      }
      const r = await h.answer(d.id, o.key, d.hash, vals); h.log(r.text); await syncStatus(h); h.ops?.invalidate()   // a status computed while the command ran may hold the card it just settled (board and ui are read apart): recompute once it returned (the engine prefixes the plugin name)
      if (!r.text.startsWith('refused')) return
      id = d.id; last = d.hash
    }
  } catch { /* dismissed, or -p: nothing is decided */ } finally { asking = false }
}

export function acts(h: Host): Acts {
  return {
    go: tab => { const pre = h.ops!.open({ ...OPEN, focus: true }); later(h, () => openPane(h, tab, { pre })) },
    pick: id => { const pre = h.ops!.open({ ...OPEN, focus: true }); later(h, async () => { await h.ui.update(u => ({ ...u, sel: id, go: false })); await openPane(h, 'epic', { pre }) }) },
    run: cmd => later(h, async () => { const r = await configPress(h, cmd); h.toast(`${r.text.split('\n')[0].slice(0, 53)}`); h.ops?.invalidate(); await autoAsk(h) }),   // a Settings toggle (a press, not a decision); edit asks its decision
    drive: what => later(h, async () => { const r = await dispatch(h, { schemaVersion: 1, cmd: 'drive', args: [what], origin: { kind: 'press' } }, ROUTES.drive); h.toast(`${r.text.split('\n')[0].slice(0, 53)}`); h.ops?.invalidate() }),   // band `0`: drive stop | resume | continue, as the human's press
    answer: id => later(h, async () => { await ack(h); await answerDialog(h, id) }),   // `1`: the decision's dialog, again
    step: (what, d) => later(h, async () => {
      const v = await read(h), ts = at(v).tasks, ids = cols(ts).flat().map(t => t.id), cur = v.t ?? v.now
      const unit = 60000 * Math.max(1, Math.ceil(((v.now - t0(v)) / 60000 + 1) / Math.max(10, (lastW || 116) - 14)))   // about one timeline column
      const go = (t: number) => ({ t: t > v.now - unit / 2 ? null : Math.max(t0(v), t) })
      const p: Record<string, unknown> = what === 'done' ? { dn: !v.ui.dn } : what === 'keys' ? { ks: v.ui.ks !== true }
        : what === 'node' ? { sel: ids[(ids.indexOf(selId(v, ts)) + d + ids.length) % ids.length] }
        : what === 'time' ? go(cur + d * unit) : { t: null, sel: undefined }
      await h.ui.update(u => ({ ...u, ...p })); await ack(h)
    }),
  }
}

export async function renderBand(h: Host, e: any, next: (e: any) => any) {
  if (e.props.hasSurvey || e.props.view?.agentId) return next(e)   // never another task's content in an agent view
  const lines = bandOf(await read(h), e.props.bodyColumns, acts(h))
  if (!lines.length) return next(e)
  const E = h.ops!.els(e)
  return E.Box({ flexDirection: 'column', children: [draw(E, lines), await next(e)] })
}
export async function renderPane(h: Host, e: any) {
  const v = await read(h), w = e.props.bodyColumns, E = h.ops!.els(e)
  lastW = w
  const p = pane(v, w, e.props.scroll.bodyRows, acts(h), e.surface === 'terminal')
  return E.Box({ flexDirection: 'column', children: [draw(E, p.before), ...(p.raster ? [E.Raster({ key: 'tl', columns: p.raster.cols, rows: p.raster.rows, cells: p.raster.cells })] : []), ...(p.after.length ? [draw(E, p.after)] : [])] })
}
// result-card row: core records tool_use_id -> task (mapCard); the task's `card` text is drawn (line 1 = summary, line 2 = next). While running or unmapped: the engine's row.
export const mapCard = (h: Host, toolUseId: string, taskId: string) => h.ui.update(u => ({ ...u, cards: { ...(u.cards as object | undefined), [toolUseId]: taskId } }))
export async function renderCard(h: Host, e: any, next: (e: any) => any) {
  const v = await read(h), id = (v.ui.cards as Record<string, string> | undefined)?.[e.props.tool_use_id], t = id ? v.b.tasks.find(x => x.id === id) : undefined
  if (e.props.isRunning || !t?.card) return next(e)
  const [row, nx] = t.card.split('\n'), k = /✗|refus|fail/i.test(row) ? 'fail' : 'done', ac = readCfg(v.ui).ascii
  return draw(h.ops!.els(e), [[S(`${ac ? '*' : '⏺'} `), S(glyph(k, ac), color(glyphRole(k))), S(` ${row}`)], ...(nx ? [[S(`  ${nx}`)]] : [])])
}
// transcript line after /clear rehydrate (6.7); the band says the rest (drive: `2: resume`)
export async function resumeBanner(h: Host, o: { decisions?: number; next?: string; stale?: number } = {}): Promise<void> {
  const v = await read(h), ts = v.b.tasks, n = ts.filter(t => kindOf(t, ts) === 'run').length, q = v.b.resumesQueued, ac = readCfg(v.ui).ascii
  if (v.ui.cont) return h.log(`${glyph('wait', ac)} unfinished plan ${v.b.plan?.id} (${prog(ts)} done) · nothing runs it now · /cadre continue or 0 picks it up`)   // an earlier session left it (core/session.rehydrate)
  h.log(`${glyph('done', ac)} resumed${v.b.mission ? ` · mission "${v.b.mission}"` : ''}${v.b.plan ? ` · epic ${v.b.plan.id}` : ''} · ${n} running (re-adopted)${o.stale ? ` · ${o.stale} stale → rebind` : ''}${q ? ` · ${q} queued` : ''}${o.next ? ` · next: ${o.next}` : ''}`)
}
// the render hook cannot read env/config, so the tick keeps the resolved strictness (M10) in the ui atom for it
export async function tickUi(h: Host): Promise<void> {
  const sx = await strictOf(h).catch(() => undefined); if (sx) await h.ui.update(u => (u.sx === sx ? u : { ...u, sx }))
  await syncTheme(h)
  h.ops?.invalidate()   // elapsed counters and `just now` age on the 30 s tick
}

files.config/index.ts:
// Config layers (DESIGN 12): defaults -> userConfig -> $HOME/.claude/cadre.json (+ repo section) -> repo .cadre/config.json -> env -> /cadre config set.
// A bad key or value is refused with a diagnostic (doctor shows them). The repo layer may only TIGHTEN S keys and may not set U keys. Metadata: REG (config/defaults).
import type { Host } from '../types'
import { repoKeyOf } from '../commands/init'
import { CATS, REG, defaults } from './defaults'
import type { Cat, Cls, Config, Meta } from './defaults'

export { defaults, REG, CATS } from './defaults'
export type { Config, Cat, Meta } from './defaults'
export type Trust = 'user' | 'repo'
export interface Layer { name: string; trust: Trust; value: unknown }

const plain = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v)
// a key, or the free-form key it lives under
const metaOf = (path: string): Meta | undefined => { for (let p = path; p; p = p.slice(0, Math.max(0, p.lastIndexOf('.')))) if (REG[p]) return REG[p]; return undefined }
export const classOf = (path: string): Cls => metaOf(path)?.cls ?? 'O'
const isOpen = (path: string) => !!metaOf(path)?.open

// what a repo layer may do to an S key: result of tightening `base` with `val`
export function tighten(path: string, base: unknown, val: unknown): unknown {
  const r = REG[path]?.tighten; if (!r) return base
  if (r === 'enum') { const o = REG[path].opts!; return o.indexOf(String(val)) > o.indexOf(String(base)) ? val : base }
  if (r === 'min') return typeof val === 'number' && val < (base as number) ? val : base
  if (r === 'grow') return Array.isArray(base) && Array.isArray(val) ? [...new Set([...base, ...val])] : base
  return Array.isArray(base) && Array.isArray(val) ? base.filter(x => val.includes(x)) : base
}
// a value against its key's allowed values: null = fine, else why
export function check(path: string, v: unknown): string | null {
  const r = REG[path]; if (!r) return null
  if (r.opts && !r.opts.includes(String(v))) return `expected one of: ${r.opts.map(o => o || "''").join(', ')}`
  if (r.min !== undefined && (typeof v !== 'number' || !Number.isFinite(v) || v < r.min || v > r.max!)) return `expected a number from ${r.min} to ${r.max}`
  return r.ok?.(v) ?? null
}

// merge one layer onto base; returns a new object and pushes a diagnostic for every ignored key
export function merge(base: Record<string, any>, layer: Record<string, any>, trust: Trust, diag: string[], path = ''): Record<string, any> {
  const out = { ...base }
  for (const [k, v] of Object.entries(layer)) {
    const p = path ? `${path}.${k}` : k
    if (!(k in base) && !isOpen(path)) { diag.push(`${p}: unknown key`); continue }
    const b = base[k]
    if (!isOpen(p) && b != null && !REG[p]?.ok && (plain(b) !== plain(v) || Array.isArray(b) !== Array.isArray(v) || typeof b !== typeof v)) { diag.push(`${p}: expected ${Array.isArray(b) ? 'a list' : plain(b) ? 'an object' : typeof b}`); continue }
    if (plain(v) && plain(b) && !isOpen(p)) { out[k] = merge(b, v, trust, diag, p); continue }   // classes apply at the leaves
    if (trust === 'repo' && classOf(p) === 'U') { diag.push(`${p}: user-level only, ignored in the repo file`); continue }
    if (trust === 'repo' && p === 'packages' && Array.isArray(v)) { out[k] = relockKnownRed(base[k], v); continue }
    const bad = check(p, v); if (bad) { diag.push(`${p}: ${bad}`); continue }
    if (trust === 'repo' && REG[p]?.tighten) { const t = tighten(p, base[k], v); if (JSON.stringify(t) !== JSON.stringify(v)) diag.push(`${p}: the repo file may only tighten this key`); out[k] = t; continue }
    out[k] = v
  }
  return out
}
// packages[].knownRed is an S key: a repo package keeps only what the user layer already granted for that root
const relockKnownRed = (prev: any[] = [], repo: any[]) => repo.map(p => { const g = prev.find(x => x.root === p.root)?.knownRed ?? []; return { ...p, knownRed: Array.isArray(p.knownRed) ? g.filter((x: string) => p.knownRed.includes(x)) : g } })

// Pure: fold layers (lowest first) onto the defaults.
export function resolve(layers: Layer[]): { config: Config; diagnostics: string[] } {
  const diagnostics: string[] = []; let config: Record<string, any> = defaults()
  for (const l of layers) {
    if (!plain(l.value)) { if (l.value !== undefined) diagnostics.push(`${l.name}: not an object, skipped`); continue }
    const d: string[] = []; const m = merge(config, l.value, l.trust, d)
    diagnostics.push(...d.map(x => `${l.name}: ${x}`)); config = m   // ponytail: bad keys are dropped per key, the rest of the layer still applies
  }
  return { config: config as Config, diagnostics }
}

const parse = (name: string, text: string | null): Layer['value'] => { if (text == null) return undefined; try { return JSON.parse(text) } catch { return `bad json in ${name}` } }
const bool = (s?: string) => (s === undefined ? undefined : s === '1' || s === 'true')
// env layer: user-level trust, so it may relax S keys (CADRE_STRICTNESS)
export const envLayer = (e: Record<string, string | undefined>): Record<string, unknown> => ({
  ...(e.CADRE_STRICTNESS ? { strictness: e.CADRE_STRICTNESS } : {}),
  ...(e.CADRE_STORE ? { store: { kind: e.CADRE_STORE } } : {}),
  ...(e.CADRE_DISABLE !== undefined ? { disable: bool(e.CADRE_DISABLE) } : {}),
  ...(e.CADRE_SPAWN ? { drive: { spawn: e.CADRE_SPAWN } } : {}),
})
// ADR 0018: a non-interactive session (claude -p) exits once no agent runs, before an agent's turn end could start the next one: drive.spawn mod runs as main
// there, unless CADRE_SPAWN=mod says so (a driver that holds stream-json stdin open). Settings shows it as forced with this reason.
export const HEADLESS = 'a non-interactive session runs main: it ends once no agent runs, before cadre could start the next one (CADRE_SPAWN=mod with stream-json input overrides)'
export const headlessMain = (spawn: string, env: Record<string, string | undefined>, headless: boolean) => headless && spawn === 'mod' && env.CADRE_SPAWN !== 'mod'

// Every layer through the Host, lowest first. `repoKey` selects the per-repo section of the home file; `root` = main checkout.
export async function layersOf(h: Host, o: { home: string; root: string; repoKey: string }): Promise<Layer[]> {
  const homeRaw = parse('cadre.json', await h.readText(`${o.home}/.claude/cadre.json`)) as Record<string, any> | undefined
  const { repos, ...home } = plain(homeRaw) ? homeRaw : ({} as Record<string, any>)
  return [
    { name: 'userConfig', trust: 'user', value: h.options.strictness ? { strictness: h.options.strictness } : {} },
    { name: '~/.claude/cadre.json', trust: 'user', value: plain(homeRaw) ? home : homeRaw },
    { name: `~/.claude/cadre.json[${o.repoKey}]`, trust: 'user', value: plain(repos) ? repos[o.repoKey] : undefined },
    { name: '.cadre/config.json', trust: 'repo', value: parse('config.json', await h.readText(`${o.root}/.cadre/config.json`)) },
    { name: 'env', trust: 'user', value: envLayer(await h.env()) },
  ]
}
export const load = async (h: Host, o: { home: string; root: string; repoKey: string }) => resolve(await layersOf(h, o))

// The one read path (ADR 0019): every module reads the effective config through cfgOf (core/dispatch re-exports it); tests/settings-registry fails on a bypass.
// h.config (hooks/register) is this same load; a Host without it (tests, dev tools) loads the layers here.
export async function cfgOf(h: Host): Promise<Config> {
  const f = (h as any).config; if (f) return f()
  const root = await h.cwd(); return (await load(h, { home: await h.home(), root, repoKey: repoKeyOf(root) })).config
}
export const strictOf = async (h: Host): Promise<string> => (await cfgOf(h).catch(() => undefined))?.strictness ?? 'strict'

// what the repo file's own refusals are (unknown key, bad value or type, a safety key loosened, a user-level key): init re-checks them after every write (ADR 0019)
export async function repoFileDiag(h: Host): Promise<string[]> {
  const root = await h.cwd(), n = '.cadre/config.json: '
  return resolve(await layersOf(h, { home: await h.home(), root, repoKey: repoKeyOf(root) })).diagnostics.filter(d => d.startsWith(n)).map(d => d.slice(n.length))
}
// Claude Code env vars that beat cadre's routing (it applies them whatever cadre passes): FORCE=1 puts every agent on CLAUDE_CODE_SUBAGENT_MODEL (unset: main's model);
// CLAUDE_CODE_EFFORT_LEVEL beats every effort. CLAUDE_CODE_SUBAGENT_MODEL alone is only a default: cadre's agent.spawn model wins over it.
export function forcedOf(env: Record<string, string | undefined>): { model?: string; effort?: string } {
  const sm = env.CLAUDE_CODE_SUBAGENT_MODEL, f = /^(1|true)$/i.test(env.CLAUDE_CODE_SUBAGENT_MODEL_FORCE ?? '')
  return { ...(f ? { model: sm && sm !== 'inherit' ? sm : "main's model" } : {}), ...(env.CLAUDE_CODE_EFFORT_LEVEL ? { effort: env.CLAUDE_CODE_EFFORT_LEVEL } : {}) }
}

// Settings rows (DESIGN 12, ADR 0019): every registered key with category, class, default, effective value and its source. Source = the last layer whose cumulative
// result differs from the one before it, so a refused repo value is not the source; 'forced' = a Claude Code env var overrides it (`warn` says how).
// ponytail: a layer that sets a key to its default reads as [default].
export type Src = 'default' | 'user' | 'repo' | 'env' | 'forced' | 'fixed' | 'tester'   // tester: a package's test check cadre adopted from the tester's command (ADR 0023)
export interface Row { key: string; cat: Cat; cls: Cls; desc: string; safety: boolean; value: unknown; def: unknown; src: Src; kind: 'bool' | 'enum' | 'number' | 'text' | 'list' | 'json'; opts?: string[]; warn?: string }
const leaves = (o: unknown, p = ''): [string, unknown][] => (plain(o) && !isOpen(p) ? Object.entries(o).flatMap(([k, v]) => leaves(v, p ? `${p}.${k}` : k)) : [[p, o]])
export const keysOf = () => leaves(defaults()).map(([k]) => k)
const at = (o: unknown, path: string) => path.split('.').reduce((a: any, k) => a?.[k], o)
const srcOf = (n: string): Src => (n === 'env' ? 'env' : n === '.cadre/config.json' ? 'repo' : 'user')
export function rows(layers: Layer[], env: Record<string, string | undefined> = {}): Row[] {
  const steps = layers.map((_, i) => resolve(layers.slice(0, i + 1)).config), fo = forcedOf(env)
  return leaves(defaults()).map(([key, def]) => {
    let src: Src = 'default', prev: unknown = def
    steps.forEach((c, i) => { const v = at(c, key); if (JSON.stringify(v) !== JSON.stringify(prev)) src = srcOf(layers[i].name); prev = v })
    const r = REG[key], opts = r.opts as string[] | undefined, mf = fo.model && /^roles\.\w+\.(byRisk\.\w+\.(escalate\.)?)?model$/.test(key), ef = fo.effort && /^roles\.\w+\.(byRisk\.\w+\.(escalate\.)?)?effort$/.test(key)
    const warn = mf || ef ? [mf && `CLAUDE_CODE_SUBAGENT_MODEL_FORCE puts every agent on ${fo.model}`, ef && `CLAUDE_CODE_EFFORT_LEVEL puts every agent on effort ${fo.effort}`].filter(Boolean).join('; ') : undefined
    if (key === 'packages' && src === 'repo' && Array.isArray(prev) && prev.some(p => p?.testBy === 'tester')) src = 'tester'
    return { key, cat: r.cat, cls: r.cls, desc: r.desc, safety: r.cls === 'S' || !!r.tighten, value: prev, def, src: warn ? 'forced' : src, kind: r.open ? 'json' : typeof def === 'boolean' ? 'bool' : opts ? 'enum' : typeof def === 'number' ? 'number' : Array.isArray(def) ? 'list' : 'text', ...(opts ? { opts } : {}), ...(warn ? { warn } : {}) }
  }).sort((a, b) => CATS.indexOf(a.cat) - CATS.indexOf(b.cat))
}

// ASCII glyphs: `ui.glyphs: ascii`, TERM=dumb, or a non-UTF-8 locale (BRAND §6)
export const asciiOf = (glyphs: string | undefined, env: Record<string, string | undefined>): boolean => {
  if (glyphs === 'ascii') return true
  if (env.TERM === 'dumb') return true
  const loc = env.LC_ALL || env.LC_CTYPE || env.LANG || ''
  return loc !== '' && !/utf-?8/i.test(loc)
}

files.commands/init.ts:
// /cadre init (ADR 0010): Claude sets the project up itself, following guides/init.md with visible tool calls. This file holds only the CHECKS (one read-only
// predicate per phase, re-run at every main turn end by commands/agentrun) and the one write the human must confirm: the containment settings (a diff on a card).
import type { Host } from '../types'
import { canon, fnv1a64 } from '../core/board'
import { DRIVE, initConfirm, initPropose, missionOf } from '../core/dispatch'
import { op } from '../core/git'
import { settle } from '../core/decide'
import { cfgOf, repoFileDiag } from '../config/index'
import type { Config } from '../config'
import { diff as jdiff } from '../policy/settings'
import { assess } from '../policy/containment'
import { StoreError } from '../task-management/store'
import type { TaskStore } from '../task-management/store'
import { validate as kac } from '../core/changelog'
import { validate as regErrors } from '../task-management/registry'
import { spec } from '../agents'
import * as D from '../core/discover'
import { realRoot, setPolicy } from '../policy/guards'
import { wtRootOf } from '../core/branches'
import { EXCLUDE_NEW, excludeFile, legacy } from '../task-management/adapters/beads/layout'

// The beads TaskStore factory (register.ts wires it). The default refuses loudly.
export const wire: { store(h: Host, cfg: Config, root: string): Promise<TaskStore> } = {
  store: async () => { throw new StoreError('Unavailable', 'task store not wired') },
}

type J = Record<string, any>
export type Item = { name: string; st: 'ok' | 'fail' | 'wait' | 'todo' | 'warn'; why?: string }   // fail = Claude's to fix (a follow-up names it); wait = the human's card; todo = after the steps above
interface Ctx { h: Host; root: string; home: string; rk: string; cfg: Config }

const base = (p: string) => p.split('/').filter(Boolean).pop() ?? 'repo'
export const repoKeyOf = (root: string) => `${base(root)}-${fnv1a64(root).slice(0, 6)}`
// an agent's cwd is <wtRoot>/<repoKey>/<task> or <repoKey>.views/<task>: map it back to the repo root recorded at session.start (the per-session secret is gone after /clear)
export const rootFor = (roots: Record<string, string> | undefined, cwd: string) => Object.entries(roots ?? {}).find(([k]) => cwd.includes(`/${k}/`) || cwd.includes(`/${k}.views/`))?.[1] ?? cwd
export const scoped = async (h: Host, name: string) => `cadre:${repoKeyOf(await h.cwd())}:${name}`   // $.store keys are per repo (13.5)
const git = (c: Ctx, ...a: string[]) => c.h.run(['git', ...a], { cwd: c.root })
const readJ = async (h: Host, p: string): Promise<J> => { const t = await h.readText(p); try { return t ? JSON.parse(t) : {} } catch { return {} } }
const union = (a: unknown, b: string[]) => [...new Set([...(Array.isArray(a) ? a : []), ...b])]
const EXCLUDE = ['.claude/settings.local.json']   // plus the store lines: layout.EXCLUDE_NEW, or .beads/ in a repo that still has it

// ---- the phases, in guide order; each answers null (done) or why not ----
async function repo(c: Ctx): Promise<string | null> {
  if ((await git(c, 'rev-parse', '--git-dir')).exitCode) return 'no git repository yet'
  if ((await git(c, 'rev-parse', '--verify', 'HEAD')).exitCode) return 'no first commit yet'
  const { main, dev } = c.cfg.branches
  if (!main) return 'branches.main is not set in .cadre/config.json'
  for (const b of [main, dev]) if ((await git(c, 'rev-parse', '--verify', b)).exitCode) return `branch ${b} is missing`
  const ex = (await git(c, 'rev-parse', '--git-path', 'info/exclude')).stdout.trim(), have = ((await c.h.readText(ex.startsWith('/') ? ex : `${c.root}/${ex}`)) ?? '').split('\n')
  const miss = [...(await legacy(c.h, c.root) ? ['.beads/'] : EXCLUDE_NEW), ...EXCLUDE].filter(w => !have.includes(w)); return miss.length ? `.git/info/exclude lacks ${miss.join(' and ')}` : null
}
async function store(c: Ctx): Promise<string | null> {
  try { const p = await (await wire.store(c.h, c.cfg, c.root)).probe(); return !p.ok ? `task store not ready: ${p.detail.slice(0, 120)}` : p.journal ? null : 'task store journal is off' }
  catch (e) { return `task store not ready: ${(e as Error).message.slice(0, 120)}` }
}
async function mission(c: Ctx): Promise<Item> {
  const b = await c.h.board.read()
  if (b.mission !== null) return { name: 'mission', st: 'ok' }
  const m = await wire.store(c.h, c.cfg, c.root).then(missionOf).catch(() => null)   // a new session: the board is cold, the recorded mission lives in the store
  if (m) { await c.h.board.update(x => ({ ...x, mission: m })); return { name: 'mission', st: 'ok' } }
  if ((await c.h.secret.read()).run?.goal) return { name: 'mission', st: 'ok', why: 'you approve it with the plan' }   // a goal run (ADR 0014): main drafts it into the plan, one dialog for both
  return b.plan?.slug === 'mission' ? { name: 'mission', st: 'wait', why: 'approve it on its card' } : { name: 'mission', st: 'fail', why: 'no mission yet' }
}
const packages = (c: Ctx): string | null => {
  if (!c.cfg.packages.length) return 'no packages in .cadre/config.json'
  const r = D.parse(c.cfg.packages); return typeof r === 'string' ? r : null
}
// the mod-run validation: every package's setup and checks in a clean offline copy at HEAD, once per package list (cached in $.store)
type Red = { root: string; n: string }
async function audit(c: Ctx): Promise<{ why: string | null; caches: string[]; red: Red[] }> {
  const pkgs = c.cfg.packages as unknown as (D.Pkg & { knownRed?: string[] })[], sig = fnv1a64(canon(pkgs)), key = `init.audit:${c.rk}`
  let a = (await c.h.store.get(key)) as { sig: string; runs: D.Run[] } | undefined
  if (a?.sig !== sig) { a = { sig, runs: [] }; for (const p of pkgs) a.runs.push(await D.exec(c.h, c.root, c.home, { ...p, setup: p.setup ?? [] }, { audit: true, knownRed: p.knownRed })); await c.h.store.set(key, a) }
  const goal = !!(await c.h.secret.read()).run?.goal, red: Red[] = []   // a goal run (ADR 0014): a check red before the goal is often the goal's own bug; it becomes known red on the safety card, never skipped or weakened
  const bad = pkgs.flatMap((p, i) => !a!.runs[i].setupOk ? [`${p.root}: setup ${(p.setup ?? []).join(' ')} fails in a clean copy`]
    : Object.entries(a!.runs[i].results).flatMap(([n, v]) => v === 'red' && goal ? (red.push({ root: p.root, n }), []) : v === 'red' ? [`${p.root}: ${n} fails on a clean checkout (fix the command or leave it out)`] : v === 'net' ? [`${p.root}: ${n} needs the network at test time (leave it out)`] : []))
  return { why: bad.length ? bad.join('; ') : null, caches: [...new Set(a.runs.flatMap(r => r.caches))], red }
}
function workflow(c: Ctx): string | null {
  const errs = regErrors(c.cfg.types as any)
  for (const r of ['worker', 'tester', 'reviewer', 'explorer'] as const) if (!spec(r, { roles: c.cfg.roles as any, mcpAllow: c.cfg.mcpAllow }).prompt) errs.push(`roles.${r} does not render`)
  return errs.length ? errs.join('; ') : null
}
async function changelog(c: Ctx): Promise<string | null> {
  const t = await c.h.readText(`${c.root}/${c.cfg.changelog.path}`); return t === null ? `${c.cfg.changelog.path} is missing` : kac(t) && `${c.cfg.changelog.path} ${kac(t)}`
}

// ---- containment: cadre writes it, after the human confirms the diff on its card ----
const SANDBOX = (wt: string, repo: string, caches: string[]) => ({
  env: { CLAUDE_CODE_ENABLE_TODO_TOOLS: '1' },
  sandbox: { enabled: true, failIfUnavailable: true, allowUnsandboxedCommands: false, autoAllowBashIfSandboxed: true, filesystem: { allowWrite: [wt, ...caches], denyWrite: [repo] } },   // ref entries are redundant under the repo-level deny (ADR 0001 S24)
})
const wtOf = async (c: Ctx) => `${await realRoot(c.h, await wtRootOf(c.h, c.cfg))}/${c.rk}`   // realpath'd like contain()'s wtRoot (symlinked ~/.cache)
const realOf = async (c: Ctx) => (await c.h.stat(c.root, { resolve: true }))?.realPath ?? c.root
async function contained(c: Ctx): Promise<boolean> {   // $.settings.read() is this session's: it shows the new file only after a restart, so a confirm this session counts
  return (await c.h.board.read()).init.some(i => i.stage === 5 && i.state === 'done') || assess(await c.h.settings().catch(() => ({})), await realOf(c), await wtOf(c)).state === 'contained'
}
const redLine = (red: Red[]) => `known red before your goal: ${red.map(x => `${x.root}: ${x.n}`).join(', ')} · it must turn green`
const grant = (pk: any[] = [], red: Red[]) => red.reduce((l, x) => (l.some(p => p.root === x.root) ? l.map(p => (p.root === x.root ? { ...p, knownRed: union(p.knownRed, [x.n]) } : p)) : [...l, { root: x.root, knownRed: [x.n] }]), pk)   // packages[].knownRed is granted only by the user layer (config relockKnownRed)
async function plan5(c: Ctx, caches: string[], red: Red[] = []) {
  const real = await realOf(c), wt = await wtOf(c), setP = `${c.root}/.claude/settings.local.json`, usrP = `${c.home}/.claude/cadre.json`, abs = caches.map(x => `${c.home}/${x}`), p = SANDBOX(wt, real, abs)
  const cur = await readJ(c.h, setP), cu = await readJ(c.h, usrP)
  const next = { ...cur, env: { ...cur.env, ...p.env }, sandbox: { ...cur.sandbox, ...p.sandbox, filesystem: { ...cur.sandbox?.filesystem, allowWrite: union(cur.sandbox?.filesystem?.allowWrite, p.sandbox.filesystem.allowWrite), denyWrite: union(cur.sandbox?.filesystem?.denyWrite, p.sandbox.filesystem.denyWrite) } } }
  const mine = { ...cu.repos?.[c.rk], ...(abs.length ? { jailWritable: union(cu.repos?.[c.rk]?.jailWritable, abs) } : {}), ...(red.length ? { packages: grant(cu.repos?.[c.rk]?.packages, red) } : {}) }
  const user = abs.length || red.length ? { ...cu, repos: { ...cu.repos, [c.rk]: mine } } : cu
  const lines = [...(red.length ? [redLine(red)] : []), ...jdiff(cur, next).map(l => `.claude/settings.local.json: ${l}`), ...jdiff(cu, user).map(l => `~/.claude/cadre.json: ${l}`)]
  const writes: [string, string][] = [[setP, JSON.stringify(next, null, 2) + '\n'], ...(user !== cu ? [[usrP, JSON.stringify(user, null, 2) + '\n'] as [string, string]] : [])]
  return { lines, writes, real, wt, sig: fnv1a64(lines.join('\n') + canon(await Promise.all([setP, usrP].map(f => c.h.readText(f))))) }
}
async function propose5(c: Ctx, caches: string[], red: Red[]): Promise<void> {
  const p = await plan5(c, caches, red); if (((await c.h.ui.read())['init.pending'] as { sig?: string } | undefined)?.sig === p.sig && (await c.h.board.read()).decisions?.some(d => d.id === 'init:5')) return
  await c.h.ui.update(u => ({ ...u, 'init.pending': { sig: p.sig, caches, red } }))
  await initPropose(c.h, 5, `init 5 containment\n${p.sig}`, { title: 'init · safety settings · confirm', short: 'init safety settings', sub: 'init', lines: ['cadre writes these settings after you confirm:', ...p.lines.slice(0, 14).map(l => `  ${l}`), ...(p.lines.length > 14 ? [`  … ${p.lines.length - 14} more lines`] : [])] })
}
// `init confirm` (the card's Confirm): the files are re-read and must match what the card showed
export async function confirm(h: Host): Promise<string> {
  const c = await ctxOf(h), pend = (await h.ui.read())['init.pending'] as { sig: string; caches: string[]; red?: Red[] } | undefined, good = await initConfirm(h, 5)
  if (!good || !pend) return 'init: nothing pending; the card shows the current diff'
  const p = await plan5(c, pend.caches, pend.red); if (p.sig !== pend.sig) return 'init: the settings files changed since you saw them; nothing written'
  for (const [path, text] of p.writes) { const old = await h.readText(path); if (old !== null && old !== text) await h.write(`${path}.bak`, old); if (old !== text) await h.write(path, text) }
  await setPolicy(h, { repo: p.real, wtRoot: p.wt, home: c.home })   // the band follows on the tick (policy/containment.heal): the session reads the new file a moment later
  await h.ui.update(({ 'init.pending': _p, ...u }) => u); await settle(h, 'init:5')
  await h.board.update(b => ({ ...b, init: [...b.init.filter(i => i.stage !== 5), { stage: 5, state: 'done' }] }))
  await restoreIgnore(h); const sha = await commitSetup(c).catch(() => null)
  return `init: safety settings written${sha ? ' · setup committed' : ''}`
}

// The setup files (config, changelog) must be committed: a clone and dev need them (a release refuses without the changelog on dev). cadre commits them after the
// safety confirm, under git.op (its own ref move is not a flag); the other branch of main/dev follows when it is an ancestor (a fresh repo), else it is left alone.
export async function commitSetup(c: Pick<Ctx, 'h' | 'root' | 'cfg'>): Promise<string | null> {
  const ex = await excludeFile(c.h, c.root); if (!ex.have.includes('.cadre/tmp/')) await c.h.write(ex.path, `${ex.have.join('\n').replace(/\n*$/, '\n')}.cadre/tmp/\n`.replace(/^\n/, ''))   // cadre's logs and scratch (core/close): never a change to commit
  const files = (await git(c as Ctx, 'status', '--porcelain', '--', '.cadre/config.json', c.cfg.changelog.path)).stdout.split('\n').filter(Boolean).map(l => l.slice(3))
  if (!files.length) return null
  const cur = (await git(c as Ctx, 'symbolic-ref', '--short', '-q', 'HEAD')).stdout.trim(), { main, dev } = c.cfg.branches, other = cur === main ? dev : cur === dev ? main : ''
  if (!other) return null
  const g = (...a: string[]) => git(c as Ctx, ...a)
  return op(c.h, async () => {
    const old = (await g('rev-parse', other)).stdout.trim()
    if ((await g('add', '--', ...files)).exitCode || (await g('commit', '--no-verify', '-m', 'chore: set up cadre', '--', ...files)).exitCode) return null
    const head = (await g('rev-parse', 'HEAD')).stdout.trim()
    if (!(await g('merge-base', '--is-ancestor', old, head)).exitCode) await g('update-ref', `refs/heads/${other}`, head, old)
    return head
  })
}
// bd init adds its own block to the root .gitignore (creating it if absent; no option turns that off while the store is inside the repo, and .git/info/exclude
// already hides the store). commands/agentrun snapshots the file when an init run starts with no task store yet; this puts it back byte-exact (gone if it was absent).
export const BD_BLOCK = '# Beads / Dolt files (added by bd init)\n.dolt/\n*.db\n.beads-credential-key\n.beads/proxieddb/\n*.gate.lock*\n'   // bd 1.3.1, verbatim
export async function restoreIgnore(h: Host): Promise<void> {
  const gi = (await h.secret.read()).run?.gi; if (!gi) return
  const path = `${await h.cwd()}/.gitignore`, now = await h.readText(path), was = gi.had ? gi.text : ''
  const onlyBd = now !== null && now.startsWith(was) && now.slice(was.length).replace(/^\n+/, '') === BD_BLOCK   // exactly what bd appends; anything else is the user's edit: never lost
  if (now !== null && now !== was) { if (!onlyBd) await h.store.set(await scoped(h, 'gitignore.review'), true); else if (gi.had) await h.write(path, gi.text); else await h.run(['rm', '-f', path]) }
  await h.secret.update(s => (s.run ? { ...s, run: { ...s.run, gi: undefined } } : s))
}
// integration green (core/integrate): a known-red check that passes now loses its mark (the user-layer grant), recorded
export async function clearKnownRed(h: Host, green: Red[], planId: string): Promise<void> {
  if (!green.length) return
  const c = await ctxOf(h), path = `${c.home}/.claude/cadre.json`, old = await h.readText(path), cu = await readJ(h, path), pk = (cu.repos?.[c.rk]?.packages ?? []) as { root: string; knownRed?: string[] }[]
  const next = pk.map(p => ({ ...p, knownRed: (p.knownRed ?? []).filter(n => !green.some(g => g.root === p.root && g.n === n)) }))
  if (JSON.stringify(next) === JSON.stringify(pk)) return
  const text = JSON.stringify({ ...cu, repos: { ...cu.repos, [c.rk]: { ...cu.repos[c.rk], packages: next } } }, null, 2) + '\n'
  const write = async () => { if (old !== null) await h.write(`${path}.bak`, old); await h.write(path, text) }
  await (DRIVE.humanWrite ? DRIVE.humanWrite(h, write) : write())   // a narrowed grant is not a change a running drive stops for
  await (await wire.store(h, c.cfg, c.root)).record('decision', `known red is green now: ${green.map(g => `${g.root}: ${g.n}`).join(', ')}`, `plan ${planId} landed with these checks passing; they gate integration again.`, planId).catch(() => {})
}

const ctxOf = async (h: Host): Promise<Ctx> => {
  const root = await h.cwd(), home = await h.home(), rk = repoKeyOf(root)
  return { h, root, home, rk, cfg: await cfgOf(h) }
}
const it = (name: string, why: string | null, blocked = false): Item => (blocked ? { name, st: 'todo', why: 'after the steps above' } : why ? { name, st: 'fail', why } : { name, st: 'ok' })
// The checklist (also doctor's project rows). Later phases that need an earlier one wait as `todo`; containment is proposed on its card once the rest passes.
// quick: what a tool result shows mid-run; no clean-checkout run, no safety card, no containment read
export async function initItems(h: Host, o: { quick?: boolean } = {}): Promise<Item[]> {
  const c = await ctxOf(h), r = await repo(c), s = r ? 'needs the repository first' : await store(c), m = await mission(c), p = packages(c)
  const a = !r && !s && !p && !o.quick ? await audit(c) : undefined, w = workflow(c), l = await changelog(c)
  const audited: Item = a && !a.why && a.red.length ? { name: 'commands pass on a clean checkout', st: 'ok', why: redLine(a.red) } : it('commands pass on a clean checkout', a?.why ?? null, !a)
  const sd = r ? [] : (await repoFileDiag(h)).map(d => d.replace(/\bjail\w*/g, 'a safety key'))   // red only: then the follow-up, the stop refusal and the tool-result line name it
  const out = [it('repository', r), ...(sd.length ? [it('settings file', `.cadre/config.json: ${sd.join('; ')}; fix or remove these keys (the user sets the rest in the cadre pane)`)] : []), it('task store', s, !!r), m, it('build and test commands', p), audited, it('workflow', w), it('changelog', l)]
  const st = (await c.h.run(['find', c.root, '-maxdepth', '4', '(', '-name', '.git', '-o', '-name', 'node_modules', ')', '-prune', '-o', '-type', 'd', '-name', '.cadre', '-print', '-prune'])).stdout.split('\n').filter(p => p.endsWith('/.cadre') && p !== `${c.root}/.cadre`).map(p => p.replace(`${c.root}/`, ''))   // made from a shell left in a package folder (live 0.10.0). ponytail: 4 levels deep
  if (st.length) out.splice(1, 0, it('no setup folder outside the root', `${st.join(', ')} is not the project root's: delete ${st.length > 1 ? 'them' : 'it'} (rm -rf ${st.map(p => `${c.root}/${p}`).join(' ')})`))
  if (o.quick) return out
  if (await contained(c)) out.push({ name: 'safety settings', st: 'ok' })
  else if (out.every(i => i.st === 'ok' || (i === m && i.st === 'wait'))) { await propose5(c, a!.caches, a!.red); out.push({ name: 'safety settings', st: 'wait', why: 'confirm them on their card' }) }
  else out.push({ name: 'safety settings', st: 'todo', why: 'after the steps above' })
  return out
}
// doctor: which phases are complete (read-only: no containment card is proposed from here)
export async function progress(h: Host): Promise<{ name: string; done: boolean }[]> {
  const c = await ctxOf(h), r = await repo(c), s = r ?? await store(c), m = await mission(c)
  return [{ name: 'repository', done: !r }, { name: 'task store', done: !s }, { name: 'mission', done: m.st === 'ok' }, { name: 'build and test commands', done: !packages(c) }, { name: 'workflow', done: !workflow(c) }, { name: 'changelog', done: !(await changelog(c)) }, { name: 'safety settings', done: await contained(c) }]
}

files.commands/prefs.ts:
// setup's Preferences phase (ADR 0014): main asks the user (AskUserQuestion) for the default mode and the drive limits and hands them over with ONE TaskCreate
// `{kind:"preferences", …}` (the only channel main has to cadre, in a dormant repo too). cadre, never Claude, writes ~/.claude/cadre.json (it holds S keys): a diff on a
// confirm card (`init:93`), then .bak, write, re-read, like the user-settings card. Only the keys that differ from the defaults are kept.
import { modelData, modelText } from '../core/say'
import type { Host } from '../types'
import { fnv1a64 } from '../core/board'
import { DRIVE, cfgOf, initConfirm, initPropose } from '../core/dispatch'
import { defaults } from '../config/index'
import { diff as jdiff } from '../policy/settings'

const CARD = 93, STAMP = 'cadre:prefs'
type Want = { mode: 'auto' | 'yolo'; maxTurns: number; maxCostUsd: number; maxWallMinutes: number; maxParallel: number; maxEpics: number }
// metadata key -> config path, the range (min..max); 0 on the two parallel keys = no cadre cap
const AT: Record<keyof Want, string[]> = { mode: ['drive', 'mode'], maxTurns: ['drive', 'maxTurns'], maxCostUsd: ['drive', 'maxCostUsd'], maxWallMinutes: ['drive', 'maxWallMinutes'], maxParallel: ['maxParallel'], maxEpics: ['milestone', 'maxEpics'] }
const LIM: [keyof Want, number, number][] = [['maxTurns', 1, 10_000], ['maxCostUsd', 1, 10_000], ['maxWallMinutes', 1, 10_080], ['maxParallel', 0, 100], ['maxEpics', 0, 100]]
const dig = (o: any, p: string[]) => p.reduce((x, k) => x?.[k], o)
const UNCAPPED = 'every parallel task is a full Claude agent: cost and load grow; drive limits still apply'
const pathOf = async (h: Host) => `${await h.home()}/.claude/cadre.json`
const readJ = (t: string | null): Record<string, any> | null => { try { const v = t ? JSON.parse(t) : {}; return v && typeof v === 'object' && !Array.isArray(v) ? v : null } catch { return null } }

// metadata -> the wanted values, or why not (an absent key keeps the default)
export function wantOf(m: Record<string, unknown>): Want | string {
  const w = Object.fromEntries(Object.entries(AT).map(([k, p]) => [k, dig(defaults(), p)])) as Want
  for (const k of Object.keys(m)) if (k !== 'kind' && !(k in AT)) return `metadata.${k}: unknown (allowed: ${Object.keys(AT).join(', ')})`
  if (m.mode !== undefined) { if (m.mode !== 'auto' && m.mode !== 'yolo') return 'metadata.mode: expected "auto" or "yolo"'; w.mode = m.mode }
  for (const [k, min, max] of LIM) if (m[k] !== undefined) { const v = m[k]; if (typeof v !== 'number' || v < min || v > max || (k !== 'maxCostUsd' && !Number.isInteger(v)) || (k === 'maxCostUsd' && !(v > 0))) return `metadata.${k}: expected a ${k === 'maxCostUsd' ? 'number' : 'whole number'} from ${min} to ${max}${min === 0 ? ' (0 = no limit)' : ''}`; (w as any)[k] = v }
  return w
}
// the user file with these choices: a default value drops its key, an emptied section goes
export function nextOf(cur: Record<string, any>, w: Want): Record<string, any> {
  const out = structuredClone(cur)
  for (const [k, p] of Object.entries(AT)) {
