  return ['ok', `your preferences: ${has ? '~/.claude/cadre.json' : 'the defaults'} (mode ${d.mode}, limits ${d.maxTurns}/$${d.maxCostUsd}/${d.maxWallMinutes}m, parallel ${n(c.maxParallel)} tasks/${n(c.milestone.maxEpics)} epics)`]
}

