// Draft + report field validation (DESIGN 3.1, 6.3). Refuses only malformed PRESENT fields, with an example-bearing error;
// completeness (scenarios, changelog decision, contract, package) is checked at approve. Pure: no Host, no store.
import type { Host } from '../types'
import type { Task } from '../task-management/store'
import { kindOf } from '../task-management/registry'
import type { TypeRegistry } from '../task-management/registry'
import { matches } from './specview'

export const FIELDS = ['kind', 'amend', 'type', 'scope', 'breaking', 'package', 'scenarios', 'changelog', 'interface', 'lane', 'reason', 'repro', 'mission', 'paths', 'core', 'notes', 'epic', 'size', 'planned', 'critique', 'assumed'] as const
export const CATEGORIES = ['Added', 'Changed', 'Deprecated', 'Removed', 'Fixed', 'Security']
const SCENARIO = /^S\d+: Given .+ When .+ Then .+$/
const STATUS = ['new', 'changed', 'unchanged']
const str = (v: unknown): v is string => typeof v === 'string' && v.trim() !== ''
const show = (v: unknown) => { const s = JSON.stringify(v); return s === undefined ? String(v) : s.length > 60 ? `${s.slice(0, 57)}...` : s }
const bad = (path: string, want: string, got: unknown) => `${path}: expected ${want}, got ${show(got)}`

// first malformed present field of a TaskCreate/TaskUpdate `metadata`, else null. null values clear a field and are fine.
export function validateFields(m: Record<string, unknown>, reg: TypeRegistry): string | null {
  for (const k of Object.keys(m)) if (!(FIELDS as readonly string[]).includes(k)) return `metadata.${k}: unknown field (allowed: ${FIELDS.join(', ')})`
  const f = (k: string) => (m[k] === null ? undefined : m[k])
  if (f('kind') !== undefined && f('kind') !== 'plan' && f('kind') !== 'mission') return bad('metadata.kind', '"plan" or "mission"', m.kind)
  if (f('amend') !== undefined && typeof m.amend !== 'boolean') return bad('metadata.amend', 'true', m.amend)
  if (f('lane') !== undefined && !['ask', 'lite', 'full', 'milestone'].includes(m.lane as string)) return bad('metadata.lane', '"ask", "lite", "full" or "milestone"', m.lane)
  if ((f('lane') !== undefined || f('reason') !== undefined) && m.kind !== 'plan') return 'metadata.lane, metadata.reason: set them on the plan\'s TaskCreate, with "kind":"plan"'
  if (f('reason') !== undefined && !str(m.reason)) return bad('metadata.reason', 'one line, e.g. "one small fix in src/a.ts"', m.reason)
  if (f('mission') !== undefined && (m.kind !== 'plan' || typeof m.mission !== 'string' || !m.mission.trim() || m.mission.length > 1000)) return bad('metadata.mission', 'on the plan\'s TaskCreate, one string "Goal: …\\nConstraints: …\\nNon-goals: …"', m.mission)   // ADR 0014: approved with the plan
  if (f('paths') !== undefined && (m.kind !== undefined || !Array.isArray(m.paths) || !m.paths.length || m.paths.length > 20 || m.paths.some((p: unknown) => !str(p) || (p as string).length > 200))) return bad('metadata.paths', 'on a task, the files or folders it will change, e.g. ["src/auth/login.ts", "test/auth/**"]', m.paths)
  if (f('core') !== undefined && (m.kind !== undefined || typeof m.core !== 'boolean')) return bad('metadata.core', 'true on the one task with the code other tasks share', m.core)
  if (f('assumed') !== undefined && (m.kind !== 'plan' || !Array.isArray(m.assumed) || !m.assumed.length || m.assumed.length > 5 || !m.assumed.every(x => str(x) && (x as string).length <= 200))) return bad('metadata.assumed', 'on the plan\'s TaskCreate, a list of 1-5 lines "<point>: what you assumed"', m.assumed)   // yolo clarify (ADR 0020): shown in the approval dialog
  if (f('notes') !== undefined && (m.kind !== 'plan' || !(str(m.notes) ? m.notes.length <= 1500 : noteList(m.notes)))) return bad('metadata.notes', 'on the plan\'s TaskCreate, what an explorer found, keyed by the paths it concerns: [{"paths":["src/auth/"],"text":"…"}] (no paths = every task; at most 3000 characters in all)', m.notes)
  if (f('epic') !== undefined && (m.kind !== undefined || !str(m.epic))) return bad('metadata.epic', 'on a task, the id of the epic it belongs to, e.g. "m-2"', m.epic)   // milestone lane (ADR 0015)
  if (f('size') !== undefined && (m.kind !== undefined || !Number.isInteger(m.size) || (m.size as number) < 1 || (m.size as number) > 7)) return bad('metadata.size', 'on an epic, how many tasks it needs, 1 to 7', m.size)
  if (f('critique') !== undefined && (m.kind !== undefined || !str(m.critique) || (m.critique as string).length > 1500)) return bad('metadata.critique', 'on the milestone, what the critic found and what you changed (at most 1500 characters)', m.critique)
  if (f('repro') !== undefined && typeof m.repro !== 'boolean') return bad('metadata.repro', 'true or false', m.repro)
  if (f('type') !== undefined && !(str(m.type) && m.type in reg)) return bad('metadata.type', `one of ${Object.keys(reg).join('|')}`, m.type)
  if (f('scope') !== undefined && !str(m.scope)) return bad('metadata.scope', '"auth"', m.scope)
  if (f('breaking') !== undefined && typeof m.breaking !== 'boolean') return bad('metadata.breaking', 'true or false', m.breaking)
  if (f('package') !== undefined && !str(m.package)) return bad('metadata.package', 'a package root, e.g. "." or "packages/api"', m.package)
  const sc = f('scenarios')
  if (sc !== undefined) {
    if (!Array.isArray(sc)) return bad('metadata.scenarios', 'an array of "S1: Given <state> When <action> Then <outcome>"', sc)
    for (const [i, s] of sc.entries()) if (typeof s !== 'string' || !SCENARIO.test(s)) return bad(`metadata.scenarios[${i}]`, `"S${i + 1}: Given <state> When <action> Then <outcome>"`, s)
  }
  const c = f('changelog') as any
  if (c !== undefined) {
    const ok = c && typeof c === 'object' && (c.none === true ? str(c.reason) : CATEGORIES.includes(c.category) && str(c.entry))
    if (!ok) return bad('metadata.changelog', `{"category":"Added","entry":"Login with email"} or {"none":true,"reason":"internal"}; category in ${CATEGORIES.join('|')}`, c)
  }
  const i = f('interface') as any
  if (i !== undefined) {
    if (!i || typeof i !== 'object') return bad('metadata.interface', '{"symbols":[{"name":"login","kind":"function","params":["email: string"],"returns":"Session","status":"new"}]} or {"none":true,"reason":"…"}', i)
    if (i.none === true) { if (!str(i.reason)) return bad('metadata.interface.reason', 'a reason', i.reason) }
    else {
      if (!Array.isArray(i.symbols) || !i.symbols.length) return bad('metadata.interface.symbols', 'a non-empty array', i.symbols)
      for (const [n, s] of i.symbols.entries()) {
        const p = `metadata.interface.symbols[${n}]`
        if (!str(s?.name) || !str(s?.kind) || !str(s?.returns)) return bad(p, '{"name","kind","params","returns","status"}', s)
        if (!Array.isArray(s.params) || s.params.some((x: unknown) => typeof x !== 'string')) return bad(`${p}.params`, 'an array of strings', s.params)
        if (!STATUS.includes(s.status)) return bad(`${p}.status`, 'new|changed|unchanged', s.status)
      }
    }
  }
  return null
}

// What a draft still lacks, from its stored form (acceptance = scenarios, design = contract, meta changelog/package). Spikes need nothing.
export function missingOf(t: Task, reg: TypeRegistry): string[] {
  if (t.type === 'epic') return [...(t.description.trim() ? [] : ['goal']), ...(t.meta['cadre.size'] ? [] : ['size']), ...(t.meta['cadre.core'] === 'true' && Number(t.meta['cadre.size']) > 2 ? ['a core epic has at most 2 tasks'] : [])]   // a roadmap epic (ADR 0015)
  const spec = reg[t.type]; if (!spec || kindOf(spec) === 'spike') return []
  const out: string[] = []
  if (t.meta['cadre.lane']?.startsWith('lite')) return [...(t.description.trim() ? [] : ['description']), ...(t.meta['cadre.changelog'] ? [] : ['changelog'])]   // lite (ADR 0011): title, description, changelog decision
  if (!t.acceptance?.trim()) out.push('scenarios')
  if (!t.meta['cadre.changelog']) out.push('changelog')
  if (spec.contract === 'required' && !t.design) out.push('interface')
  if (!t.meta['cadre.package']) out.push('package')
  return out
}
// every draft's gaps as "id: a, b"; a plan with no tasks lacks "tasks". Empty = approvable. With two or more code tasks each declares its paths, and two tasks
// that would change the same path must be ordered by a blocks dependency (or the shared code moves into one core task): parallel edits of one file conflict (ADR 0014 G)
export function missingList(drafts: Task[], reg: TypeRegistry): string[] {
  if (!drafts.length) return ['tasks']
  const ep = drafts[0].type === 'epic', code = drafts.filter(t => t.type === 'epic' || (reg[t.type] && kindOf(reg[t.type]) !== 'spike')), many = code.length >= 2
  const out = drafts.flatMap(t => { const m = [...missingOf(t, reg), ...(many && code.includes(t) && !pathsOf(t).length ? ['paths'] : [])]; return m.length ? [`${t.id}: ${m.join(', ')}`] : [] })
  const after = (a: Task, b: Task, seen = new Set<string>()): boolean => a.deps.some(d => ['blocks', 'waits-for'].includes(d.type) && !seen.has(d.id) && (seen.add(d.id), d.id === b.id || (drafts.some(x => x.id === d.id) && after(drafts.find(x => x.id === d.id)!, b, seen))))
  for (let i = 0; i < code.length; i++) for (const b of code.slice(i + 1)) {
    const a = code[i], p = pathsOf(a).find(x => pathsOf(b).some(y => overlap(x, y)))
    if (p && !after(a, b) && !after(b, a)) out.push(`${a.id}+${b.id} both change ${p}: ${ep ? 'move it into the core epic or add a dependency' : 'move it into one core task or add a blocks dependency'}`)
  }
  return ep && drafts.length < 2 ? [...out, 'epics: a milestone has 2 or more (else change the lane to one plan)'] : out
}
// declared paths (metadata.paths -> cadre.paths) and their overlap: equal, a folder of the other, or a glob that matches it
// metadata.notes (ADR 0022): [{paths?, text}]; the old plain string is one note for every task
export interface Note { paths?: string[]; text: string }
const noteList = (v: unknown): boolean => Array.isArray(v) && v.length > 0 && v.every(n => n && str(n.text) && (n.paths === undefined || (Array.isArray(n.paths) && n.paths.length > 0 && n.paths.every(str)))) && v.reduce((k, n) => k + n.text.length, 0) <= 3000
export const notesOf = (raw?: string): Note[] => { if (!raw?.trim()) return []; try { const v = JSON.parse(raw); if (noteList(v)) return v } catch { /* plain text */ } return [{ text: raw.trim() }] }
// shared: notes without paths (the plan block, same for every task); slice: the notes whose paths overlap the task's (its task block), all path notes for a task
// that declares none. notes.slice off: every note is shared.
export function sliceNotes(notes: Note[], paths: string[], slice: boolean): { shared: string; slice: string } {
  const txt = (ns: Note[]) => ns.map(n => n.text.trim()).join('\n'), pathed = (n: Note) => slice && !!n.paths?.length
  return { shared: txt(notes.filter(n => !pathed(n))), slice: txt(notes.filter(n => pathed(n) && (!paths.length || n.paths!.some(p => paths.some(q => overlap(p, q)))))) }
}
// review coverage (ADR 0022): the scenario ids (S1, S2…) of the acceptance that no locked spec test name carries ("test_s3_login" carries S3, "S30" does not)
export const scenarioIds = (acceptance?: string): string[] => (acceptance ?? '').split('\n').map(l => /^S\d+/.exec(l.trim())?.[0]).filter(Boolean) as string[]
// names null: the task has no locked spec tests (no tester step), nothing to check
export const specTestsOf = (t: Pick<Task, 'meta'>): string[] | null => { try { const v = JSON.parse(t.meta['cadre.specTests'] ?? 'null'); return Array.isArray(v) ? v.map(String) : null } catch { return null } }
export const untested = (acceptance: string | undefined, names: string[] | null): string[] => !names ? [] : scenarioIds(acceptance).filter(id => !names.some(n => new RegExp(`(?<![A-Za-z0-9])${id}(?![0-9])`, 'i').test(n)))
// what blocks a pass: untested scenarios, and coverage entries the reviewer did not mark ok:true (missing or weak). Off: nothing.
export function coverageGaps(enforce: boolean, acceptance: string | undefined, names: string[] | null, coverage: unknown): string[] {
  if (!enforce) return []
  const key = (s: unknown) => /^S\d+/.exec(String(s))?.[0] ?? String(s), cov = Array.isArray(coverage) ? coverage : []
  const weak = cov.filter((c: any) => c?.ok !== true).map((c: any) => `scenario ${key(c?.scenario)} is not covered by a test that checks it`)
  return [...untested(acceptance, names).map(id => `scenario ${id} has no test`), ...weak]
}
export const pathsOf = (t?: Pick<Task, 'meta'>): string[] => { try { return JSON.parse(t?.meta['cadre.paths'] || '[]') } catch { return [] } }
const dir = (p: string) => p.replace(/\/\*\*?$/, '').replace(/\/$/, '')
export const overlap = (a: string, b: string): boolean => dir(a) === dir(b) || b.startsWith(`${dir(a)}/`) || a.startsWith(`${dir(b)}/`) || matches([a], b) || matches([b], a)
// the byte-stable context line, ≤200 chars
export const missingLine = (list: string[]): string => (list.length ? `missing: ${list.join('; ')}`.slice(0, 200) : '')

// retries ≤3 per draft (DESIGN 3.1, 7): the counter lives in the local `ui` atom. Returns the text to refuse with.
export const RETRIES = 3
export async function refuse(h: Host, key: string, err: string): Promise<string> {
  let n = 0
  await h.ui.update(u => { const r = { ...((u.retries as Record<string, number>) ?? {}) }; n = r[key] = (r[key] ?? 0) + 1; return { ...u, retries: r } })
  return tried(err, n, key)
}
export const tried = (err: string, n: number, key: string) => (n > RETRIES ? `${err} (retry cap ${RETRIES} reached for ${key}: ask the human, or start a new draft)` : `${err} (attempt ${n}/${RETRIES})`)
export const clearRetries = (h: Host, key: string) => h.ui.update(u => { const { [key]: _x, ...r } = (u.retries as Record<string, number>) ?? {}; return { ...u, retries: r } })
export async function capped(h: Host, key: string): Promise<boolean> { return (((await h.ui.read()).retries as Record<string, number>) ?? {})[key] >= RETRIES + 1 }

// Report envelope (DESIGN 6.2): entry point for wave 3 (`tools/index`); semantic checks (6.3: files exist at sourceCommit...) are theirs to add.
// Returns an example-bearing error or null.
// the tester's test command (ADR 0023): an argv run without a shell, inside the offline sandbox like any check. Only a test runner: a shell or a file/git/network
// tool as argv[0] is refused (the jail discards writes and has no network, but with jail off it runs on the host; the tests themselves are code the checks run anyway)
const NOT_RUNNER = /^(sh|bash|zsh|dash|ksh|fish|env|sudo|su|doas|rm|mv|cp|dd|ln|chmod|chown|git|curl|wget|ssh|scp|nc|kill|xargs)$/
export function runShape(run: any): string | null {
  const eg = 'e.g. {"command":["node","--test","test/login.test.js"]}'
  if (!run || typeof run !== 'object' || !Array.isArray(run.command) || !run.command.length || run.command.length > 64 || !run.command.every((a: unknown) => typeof a === 'string' && a && a.length < 1000)) return `run.command: expected the argument list that runs only your tests, no shell, ${eg}`
  if (NOT_RUNNER.test(String(run.command[0]).split('/').pop()!)) return `run.command: "${run.command[0]}" is not a test runner; give the runner itself, ${eg}`
  if (run.cwd !== undefined && (typeof run.cwd !== 'string' || run.cwd.startsWith('/') || run.cwd.split('/').includes('..'))) return 'run.cwd: expected a folder relative to your test folder, e.g. "web"'
  if (run.junit !== undefined && typeof run.junit !== 'string') return 'run.junit: expected "$CADRE_JUNIT" (the path your runner writes its JUnit XML report to)'
  return null
}
const ROLE_KEYS: Record<string, string[]> = { worker: ['outcome', 'summary'], tester: ['outcome', 'summary', 'tests'], reviewer: ['verdict', 'summary', 'findings', 'coverage', 'contractStatus'], explorer: [], planner: ['tasks'] }
export function validateReport(r: any): string | null {
  if (!r || typeof r !== 'object') return bad('report', '{"schemaVersion":1,"role":"worker","outcome":"done","summary":"…"}', r)
  if (r.schemaVersion !== 1) return bad('schemaVersion', '1', r.schemaVersion)
  if (!(r.role in ROLE_KEYS)) return bad('role', 'worker|tester|reviewer|explorer|planner', r.role)
  const miss = ROLE_KEYS[r.role].find(k => r[k] === undefined); if (miss) return `${miss}: required for role ${r.role}`
  if (r.role === 'explorer' && !str(r.answer)) return 'answer: required for role explorer'
  if (r.role === 'worker' && !['done', 'blocked', 'spec_change'].includes(r.outcome)) return bad('outcome', 'done|blocked|spec_change', r.outcome)
  if (r.role === 'reviewer' && !['pass', 'changes'].includes(r.verdict)) return bad('verdict', 'pass|changes', r.verdict)
  if (r.role === 'tester' && r.run !== undefined) { const e = runShape(r.run); if (e) return e }
  if (typeof r.summary === 'string' && r.summary.length > 1500) return `summary: at most 1500 chars, got ${r.summary.length}`
  return null
}

files.agents/index.ts:
// Roster (DESIGN 4.1): 4 agent types, shipped as plugin agent files agents/<role>.md (A28: per-agent experimental.cacheTtl; their body = PROMPTS, tools = TOOLS, test-pinned).
// The `tools` list is also the role's L1 allowlist (default-deny by name). Grep/Glob are absent in 2.1.295 (S45): no search tools; briefs name paths.
import { modelText } from '../core/say'
import type { Role } from '../types'
import { PROMPTS } from './prompts'

const R = 'mcp__cadre__report', C = 'mcp__cadre__run_check', I = 'mcp__cadre__inspect'
export const TOOLS: Record<Role, readonly string[]> = {
  worker: ['Read', 'Edit', 'Write', 'NotebookEdit', 'Bash', 'PowerShell', 'Monitor', 'TodoWrite', R, C],
  tester: ['Read', 'Write', 'Edit', R],
  reviewer: ['Read', I, C, R],
  explorer: ['Read', I, R],
  planner: ['Read', I, R],
}
// main: no shell, no Cron*/ScheduleWakeup (a second loop owner, DESIGN 9). File tools are fenced (policy/guards).
export const MAIN_TOOLS: readonly string[] = ['Read', 'LSP', 'WebFetch', 'WebSearch', 'ToolSearch', 'TaskCreate', 'TaskUpdate', 'TaskList', 'TaskGet',
  'Agent', 'AskUserQuestion', 'SendMessage', 'Skill', 'Edit', 'Write', 'NotebookEdit', I]
const DESC: Record<Role, string> = {
  worker: 'implements one approved task in its own folder',
  tester: 'writes black-box tests for one task from its scenarios',
  reviewer: 'reviews one task commit against its scenarios',
  explorer: 'read-only recon, discovery and spikes',
  planner: 'drafts the task plan of one epic, read-only',
}
// allowlist for a role: its tools, plus the user's mcpAllow for the worker (SA: user-level S key)
export const allowlist = (role: Role, mcpAllow: readonly string[] = []): string[] => [...TOOLS[role], ...(role === 'worker' ? mcpAllow : [])]

export interface Roles { [k: string]: { model?: string; effort?: string; byRisk?: Record<string, { model?: string; effort?: string }> } }
// A role's spec as config resolves it (init stage 6 renders one per role): model/effort of its standard-risk cell (explorer: its own), 'default' effort left out.
export function spec(role: Role, cfg: { roles: Roles; mcpAllow: readonly string[] }) {
  const r0 = cfg.roles[role] ?? {}, r = r0.byRisk?.standard ?? r0
  return { name: role, description: DESC[role], prompt: modelText('agent-brief', PROMPTS[role]), tools: allowlist(role, cfg.mcpAllow), ...(r.model ? { model: r.model } : {}), ...(r.effort && r.effort !== 'default' ? { effort: r.effort } : {}) }
}
// The plugin agent file agents/<role>.md, byte for byte (tests compare it with the shipped file). No model: admission sets it per spawn from config.
// Prompt-cache TTL per role (A28, S44, ADR 0022): 1h for worker/tester/reviewer (same-role spawns are 5-60 min apart) and the planner (a milestone's planners
// start minutes apart, ADR 0021; effort high = roles.planner's default, for its first request, before admission binds it); the one-shot explorer an explicit 5m (cheaper writes). Shipped in the files, so it is a fixed row in settings (config/route), not a knob. The explorer also keeps low effort.
export const TTL: Record<Role, '5m' | '1h'> = { worker: '1h', tester: '1h', reviewer: '1h', explorer: '5m', planner: '1h' }
export const ROLES: readonly Role[] = ['worker', 'tester', 'reviewer', 'explorer', 'planner']
export const file = (role: Role): string => ['---', `name: ${role}`, `description: "${DESC[role]}"`, `tools: ${TOOLS[role].join(', ')}`,
  ...(role === 'explorer' ? ['effort: low'] : role === 'planner' ? ['effort: high'] : []), 'experimental:', `  cacheTtl: ${TTL[role]}`, '---', PROMPTS[role], ''].join('\n')

files.core/specview.ts:
// Spec view (DESIGN 3.5.1, 3.5.3): the tester's tree, built by COPYING blobs (never symlinks) at the base, with a content hash per file and a call log for the audit.
// Paths in the view are package-relative: view/<p> <-> <wt>/<pkg.root>/<p>. Everything runs through h.run / h.write (ADR 0003).
import { modelText } from './say'
import type { Host } from '../types'
import type { Task } from '../task-management/store'
import { StoreError } from '../task-management/store'
import type { Deps } from './admission'
import { renderContract } from './briefs'
import * as G from './git'

export interface Pkg { root: string; setup?: string[]; checks: Record<string, string[]>; verify?: string[]; knownRed?: string[]; viewInclude?: string[]; tdd?: { check?: string; paths: string[]; report?: string; stubs?: string[]; skeleton?: string[] } }

// Longest segment-aware root prefix of the task's package (10.2.6).
export const pkgOf = (d: Deps, task: Pick<Task, 'meta'>): Pkg | undefined => {
  const all = d.cfg.packages as Pkg[], at = task.meta['cadre.package'] || (all.length === 1 ? all[0].root : '.')   // no package named: the only one there is (a monorepo with one package in kit/ blocked every unnamed task as "no package", live 0.9.1)
  return all.filter(p => p.root === '.' || at === p.root || at.startsWith(`${p.root}/`)).sort((a, b) => b.root.length - a.root.length)[0]
}
export const rootOf = (p?: Pkg) => (!p || p.root === '.' ? '' : p.root)
// jail: off = run unsandboxed; auto = the sandbox when this machine has one; on = the sandbox or nothing (the check fails with the reason)
export async function modeOf(h: Host, d: Pick<Deps, 'cfg'>): Promise<'overlay' | 'copy' | 'none'> {
  if (d.cfg.jail === 'off') return 'none'
  const m = await G.jailMode(h.run); if (m === 'none' && d.cfg.jail === 'on') throw new Error('checks cannot run here: the isolated runner they require is missing; ask the human to run /cadre doctor')
  return m
}

// Globs: `**` any depth, `*` within a segment, `?` one char; a bare directory matches everything under it.
export const globRe = (g: string) => new RegExp(`^${g.replace(/\*\*\/|\*\*|\*|\?|[.+^${}()|[\]\\]/g, m => (m === '**/' ? '(?:.*/)?' : m === '**' ? '.*' : m === '*' ? '[^/]*' : m === '?' ? '[^/]' : `\\${m}`))}$`)
export const matches = (globs: readonly string[], p: string) => globs.some(g => globRe(g).test(p) || p.startsWith(`${g.replace(/\/$/, '')}/`))

const sh = (h: Host, argv: string[], cwd?: string) => h.run(argv, { cwd, timeoutMs: 120000 })
const must = async (h: Host, argv: string[], cwd?: string) => { const r = await sh(h, argv, cwd); if (r.exitCode) throw new Error(`${argv[0]} failed: ${r.stderr.slice(0, 200)}`); return r.stdout }
const list = async (h: Host, dir: string, type: 'f' | 'l') => (await must(h, ['find', '.', '-type', type, '-print0'], dir)).split('\0').filter(Boolean).map(p => p.replace(/^\.\//, ''))

// path -> blob hash of every regular file under dir (git hash-object works outside a repo; --no-filters = raw bytes)
export async function hashes(h: Host, dir: string): Promise<Record<string, string>> {
  const files = (await list(h, dir, 'f')).sort(), out: Record<string, string> = {}
  for (let i = 0; i < files.length; i += 200) {
    const part = files.slice(i, i + 200), lines = (await must(h, ['git', 'hash-object', '--no-filters', '--', ...part], dir)).split('\n')
    part.forEach((f, k) => { out[f] = lines[k] })
  }
  return out
}

// Build `<wtRoot>/<repoKey>.views/<id>/` (outside the worker allowWrite). Source = the spec commit when a spec exists (rebuild after accept), else the base. Returns the view path.
export async function buildView(h: Host, d: Deps, task: Task, wt: string): Promise<string> {
  const pkg = pkgOf(d, task), root = rootOf(pkg), paths = pkg?.tdd?.paths ?? []
  if (!paths.length) throw new StoreError('Invalid', `${task.id}: its package has no test paths (tdd.paths); ask the human to run /cadre init`)
  const view = `${d.wtRoot}/${d.key}.views/${task.id}`, scratch = `${d.wtRoot}/${d.key}.scratch/${task.id}-view`, src = task.meta['cadre.specCommit'] ?? task.meta['cadre.base'] ?? (await G.tip(h.run, wt, 'HEAD'))
  await sh(h, ['rm', '-rf', view, scratch]); await must(h, ['mkdir', '-p', view, `${scratch}/x`, `${scratch}/stubs`])
  const want = [...paths, ...(pkg?.viewInclude ?? [])], take: string[] = []
  for (const rec of (await G.git(h.run, wt, ['ls-tree', '-r', '-z', '--full-tree', src])).split('\0').filter(Boolean)) {   // "<mode> <type> <sha>\t<path>"
    const tab = rec.indexOf('\t'), mode = rec.slice(0, 6), path = rec.slice(tab + 1)
    if (root && !path.startsWith(`${root}/`)) continue
    if (!matches(want, root ? path.slice(root.length + 1) : path)) continue
    if (mode === '100644' || mode === '100755') take.push(path); else h.log(`view ${task.id}: skipped ${path} (mode ${mode}, not a regular file)`)
  }
  if (take.length) {
    await G.git(h.run, wt, ['archive', '--format=tar', '-o', `${scratch}/v.tar`, src, '--', ...take]); await must(h, ['tar', '-xf', `${scratch}/v.tar`, '-C', `${scratch}/x`])
    await must(h, ['cp', '-a', `${scratch}/x/${root ? `${root}/` : ''}.`, view])
  }
  // FILES.md: the agent's tools cannot list directories, so the view names its files. SCENARIOS.md: a lite bug fix (ADR 0011) has no scenarios; its
  // title and description are the bug to reproduce (live 0.8.0: an empty spec left the tester nothing to make red). Dev reasons stay here, never in the text.
  await h.write(`${view}/FILES.md`, modelText('agent-file', `# Files in this view\n\nRead these files for this project's test conventions (runner, import style, naming):\n\n${take.map(p => `- ${root ? p.slice(root.length + 1) : p}`).join('\n') || '(none)'}\n`))
  const bug = `No scenarios were written for this fix. Write one test that reproduces the bug described below: it must fail now and pass once the bug is fixed.\n\n${task.title}\n${task.description ?? ''}`
  await h.write(`${view}/SCENARIOS.md`, modelText('agent-file', `# Scenarios ${task.id}\n\n${task.acceptance?.trim() ? task.acceptance : bug}\n`))
  await h.write(`${view}/INTERFACE.md`, modelText('agent-file', `# Interface ${task.id}\n\n${renderContract(task.design)}\n\n\`\`\`json\n${task.design ?? ''}\n\`\`\`\n`))
  if (pkg?.tdd?.stubs) {   // generator output only, run in the offline jail; CADRE_OUT is where it writes
    const mode = await modeOf(h, d), out = mode === 'none' ? `${scratch}/stubs` : '/tmp/stubs', cwd = root ? `${wt}/${root}` : wt
    const r = await G.checkRun(h.run, mode, { wt, scratch, pkgRoot: cwd, argv: pkg.tdd.stubs, env: { CADRE_OUT: out } })
    if (r.exitCode) throw new StoreError('Invalid', `${task.id}: stubs failed: ${r.stderr.slice(-200)}`)
    await must(h, ['cp', '-a', `${scratch}/stubs/.`, view])
  }
  for (const l of await list(h, view, 'l')) { await sh(h, ['rm', '-f', `${view}/${l}`]); h.log(`view ${task.id}: dropped symlink ${l}`) }
  await d.store.setMeta(task.id, { 'cadre.view': JSON.stringify(await hashes(h, view)) }, d.actor)
  await sh(h, ['rm', '-rf', scratch])
  return view
}

// ---- call log (3.5.2): w3-reuse's tool.call wrap calls logCall for every tester call; the audit reads it ----
const lk = (agentId: string) => `cadre:tlog:${agentId}`
export interface Call { tool: string; path?: string; outcome: string }
export async function logCall(h: Host, agentId: string, call: Call): Promise<void> {
  const q = ((await h.store.get(lk(agentId))) as Call[] | undefined) ?? []
  await h.store.set(lk(agentId), [...q, call].slice(-300))
}

// ---- audit at report (3.5.3): hashes vs the build; only files under tdd.paths may differ ----
export interface Audit { changed: string[]; outside: string[]; calls: number; denied: number; text: string }
export async function auditView(h: Host, d: Deps, task: Task, view: string, agentId?: string): Promise<Audit> {
  const built = JSON.parse(task.meta['cadre.view'] ?? '{}') as Record<string, string>, now = await hashes(h, view), paths = pkgOf(d, task)?.tdd?.paths ?? []
  const changed = [...new Set([...Object.keys(built), ...Object.keys(now)])].filter(p => built[p] !== now[p]).sort(), outside = changed.filter(p => !matches(paths, p) || p === 'SCENARIOS.md' || p === 'INTERFACE.md')
  const log = agentId ? ((await h.store.get(lk(agentId))) as Call[] | undefined) ?? [] : [], denied = log.filter(c => c.outcome !== 'ok').length
  const text = `tester audit: ${changed.length} file(s) changed, ${outside.length} outside tdd.paths${outside.length ? ` (${outside.slice(0, 5).join(', ')})` : ''}; ${log.length} call(s), ${denied} refused`
  if (agentId) await h.store.del(lk(agentId))
  await d.store.comment(task.id, `[cadre:tester-log v1] ${text}`, d.actor)
  return { changed, outside, calls: log.length, denied, text }
}

files.core/rebase.ts:
// Parallel tasks in one plan (ADR 0014 G). A task whose squash would conflict, or whose checks go red on the moved plan branch, is reworked by the SAME worker on
// the new tip (the mod merges the tip into its branch under git.op, conflicts left in its tree; locked spec tests keep this task's version), then green -> re-review
// -> squash again. At most limits.rebaseRounds per task; then the caller blocks it (auto: a dialog; yolo: the rest of the plan goes on, core/drive). Running siblings get the new
// tip merged in after every squash, and a trial merge (git merge-tree, >= 2.38) warns two running workers early when their changes collide.
import { modelText } from './say'
import type { Host, SnapTask } from '../types'
import type { Task } from '../task-management/store'
import type { Deps } from './admission'
import { agentsOf } from './board'
import { apply } from './machine'
import { pipeOf } from '../task-management/registry'
import { idsIn, pushDelta } from './briefs'
import { mirror } from './dispatch'
import { setup } from './admission'
import { baseOf, taskBranch, wtPath } from './branches'
import { decided } from './drive'
import { ask } from './decide'
import { card } from './render'
import { policyOf, setPolicy } from '../policy/guards'
import { overlap, pathsOf } from './validate'
import * as G from './git'
import { budgetOf, charge, step } from './lifecycle'

const num = (v?: string) => Number(v ?? 0) || 0
const sha7 = (s: string) => s.slice(0, 7)
const lines = (s: string) => s.split('\n').filter(Boolean)
const worker = async (h: Host, id: string) => { const b = await h.bind.read(); return agentsOf(b, id).find(a => !a.startsWith('~') && b[a].role === 'worker') }

// trial merge without touching any tree: null = clean, [] / files = conflicting paths, undefined = this git has no merge-tree --write-tree (< 2.38)
export async function trial(h: Host, root: string, a: string, b: string): Promise<string[] | null | undefined> {
  const r = await h.run(['git', '-C', root, 'merge-tree', '--write-tree', '--name-only', '--no-messages', a, b])
  return r.exitCode === 0 ? null : r.exitCode === 1 ? lines(r.stdout).slice(1) : undefined
}
// the tasks whose squash commits since `from` touched these files (their `Refs: <id>` trailer)
const landed = async (h: Host, root: string, from: string, to: string, files: string[]) =>
  idsIn(await G.git(h.run, root, ['log', '--format=%B', `${from}..${to}`, ...(files.length ? ['--', ...files] : [])]), (await h.board.read()).tasks.map(t => t.id))

// One rework round. Returns the text for main, or null when the cap is reached (the caller blocks the task and asks).
export async function rework(h: Host, d: Deps, t: SnapTask, task: Task, tip: string, why: 'conflict' | 'red', detail = ''): Promise<string | null> {
  const n = (await budgetOf(h, t.id)).rebase + 1, ROUNDS = d.cfg.limits.rebaseRounds, wt = task.meta['cadre.worktree'], br = task.meta['cadre.branch'], base = task.meta['cadre.base'] ?? tip
  if (n > ROUNDS || !wt || !br) return null
  const locked = ((await policyOf(h)).locks?.[t.id] ?? []).map(p => p.slice(wt.length + 1))
  const conf = await G.op(h, async () => {
    await h.run(['git', '-C', wt, 'checkout', '-q', '-f', br])
    if (!(await h.run(['git', '-C', wt, 'merge', '--no-ff', '--no-edit', '-m', `merge the plan tip ${sha7(tip)} into ${t.id}`, tip])).exitCode) return [] as string[]
    const c = lines(await G.git(h.run, wt, ['diff', '--name-only', '--diff-filter=U']))
    for (const p of c.filter(p => locked.includes(p))) { await G.git(h.run, wt, ['checkout', '--ours', '--', p]); await G.git(h.run, wt, ['add', '--', p]) }   // a locked spec test keeps this task's version
    return c.filter(p => !locked.includes(p))
  })
  const by = await landed(h, d.root, base, tip, conf), p = pipeOf(d.reg), at = await h.now()
  const m = await apply(h, { kind: 'rewind', id: t.id, at, actor: 'mod', on: 'worker' }, p); if (!m.ok) throw new Error(m.error)
  await d.store.resume(t.id, d.actor)
  await charge(h, t.id, 'rebase'); await d.store.setMeta(t.id, { 'cadre.base': tip, 'cadre.review': '', 'cadre.step': 'worker' }, d.actor)
  const text = modelText('nudge', [`The plan moved on while ${t.id} waited to merge${by.length ? `: ${by.join(', ')} landed` : ''}. Your branch now has the new plan tip merged in (round ${n}/${ROUNDS}).`,
    conf.length ? `Resolve the conflicts in: ${conf.join(', ')} (keep both changes where they do not contradict).` : `Its checks fail on the merged tree${detail ? `:\n${detail.slice(0, 800)}` : ''}.`,
    'Keep your change, keep every test green; locked tests stay as they are. Then report done again.'].join('\n'))
  const w = await worker(h, t.id); if (w) await step(h, w, { type: 'resume', text })
  await decided(h, 'rebase', `${t.id}: reworked onto the plan tip ${sha7(tip)} (${why}${by.length ? ` after ${by.join(', ')}` : ''}), round ${n}/${ROUNDS}`, t.id)
  await h.board.update(s => ({ ...s, tasks: s.tasks.map(x => (x.id === t.id ? { ...x, card: card({ id: t.id, title: t.title, role: 'main', to: 'worker', flags: x.flags, next: w ? 'worker resumed: it updates its change onto the plan' : `spawn TASK-${t.id} (worker)` }) } : x)) }))
  return `${t.id} was not merged: the plan moved (${why === 'conflict' ? `conflicts in ${conf.join(', ') || 'its files'}` : 'its checks fail on the new tip'}). Its worker updates it (round ${n}/${ROUNDS}); it comes back for review. ${w ? 'Wait for it (TaskList).' : `Spawn TASK-${t.id} again.`}`
}
// past the cap: the human sees both sides (auto: the dialog; yolo: the task stays blocked while the rest goes on, core/drive)
export async function capAsk(h: Host, d: Deps, t: SnapTask, task: Task, tip: string, files: string[]): Promise<void> {
  const by = await landed(h, d.root, task.meta['cadre.base'] ?? tip, tip, files)
  await ask(h, { id: `flag:${t.id}:conflict`, kind: 'flag', title: `${t.id} still conflicts after ${d.cfg.limits.rebaseRounds} reworks`, short: `${t.id} conflict`, hash: `conflict:${sha7(tip)}`, tab: 'epic', sel: t.id,
    lines: [t.title, `with ${by.join(', ') || 'work that landed'} on ${files.slice(0, 4).join(', ') || 'the merged tree'}`, 'Retry: one more rework round by its worker. Cancel task: end it, the rest of the plan goes on.'],
    options: [{ key: 'r', label: 'Retry', verb: 'change', run: `resolve ${t.id} rebase` }, { key: 'x', label: 'Cancel task', verb: 'cancel', run: `resolve ${t.id} cancel` }] })
}

// after a squash into the plan branch: merge the new tip into every running worker's branch (a throwaway worktree, then the branch ref and the live tree move);
// a sibling that would conflict is told now and reworked at its own merge
export async function refresh(h: Host, d: Deps, tip: string, from: string, only?: string): Promise<void> {
  const all = (await h.board.read()).tasks, ep = only ?? all.find(x => x.id === from)?.epic   // a milestone: only the same epic's workers (another epic's branch gets the milestone tip at its own landing)
  for (const x of all.filter(x => x.id !== from && x.epic === ep && x.state === 'active' && x.step === 'worker')) {
    const task = await d.store.get(x.id).catch(() => null), wt = task?.meta['cadre.worktree'], br = task?.meta['cadre.branch']
    if (!task || !wt || !br || !(await h.stat(wt))) continue
    const head = await G.tip(h.run, d.root, br), c = await trial(h, d.root, head, tip), w = await worker(h, x.id)
    if (c === undefined || (c === null && (await G.ok(h.run, d.root, ['merge-base', '--is-ancestor', tip, head])))) continue
    if (c?.length) { if (w) await pushDelta(h, w, modelText('context', `Heads-up: ${from} landed and changes ${c.join(', ')} too. Your change will be merged onto it when you finish; keep your edits there small.`)); continue }
    const tmp = `${d.wtRoot}/${d.key}.scratch/refresh-${x.id}`, moved = await G.op(h, async () => {
      await h.run(['git', '-C', d.root, 'worktree', 'add', '-f', '--detach', tmp, head])
      try {
        if ((await h.run(['git', '-C', tmp, 'merge', '--no-ff', '--no-edit', '-m', `merge the plan tip ${sha7(tip)} into ${x.id}`, tip])).exitCode) return false
        const next = await G.tip(h.run, tmp, 'HEAD')
        if (!(await G.casRef(h.run, d.root, `refs/heads/${br}`, next, head))) return false
        if ((await h.run(['git', '-C', wt, 'read-tree', '-m', '-u', head, next])).exitCode) { await G.casRef(h.run, d.root, `refs/heads/${br}`, head, next); return false }   // the worker's own edits touch the same files: leave its tree alone
        return true
      } finally { await h.run(['git', '-C', d.root, 'worktree', 'remove', '--force', tmp]) }
    })
    if (!moved) continue
    await d.store.setMeta(x.id, { 'cadre.base': tip }, d.actor)
    if (w) await pushDelta(h, w, modelText('context', `${from} landed; your branch now includes it (plan tip ${sha7(tip)}). Your edits are kept.`))
  }
}

// tick (every 60 s): a trial merge of every pair of running workers' trees (uncommitted edits included, via stash create); on a collision both are told once.
// Without merge-tree (git < 2.38) the declared paths (metadata.paths) are compared instead.
export async function watch(h: Host, d: Deps): Promise<void> {
  const s = await h.board.read(), run = s.tasks.filter(x => x.state === 'active' && x.step === 'worker'), eps = (s.plan?.epics ?? []).filter(e => e.state === 'running'); if (run.length < 2 && eps.length < 2) return
  const seen = ((await h.store.get(`cadre:${d.key}:collide`)) as string[] | undefined) ?? [], tips: Record<string, string> = {}, meta: Record<string, Task> = {}
  for (const x of run) {
    const task = await d.store.get(x.id).catch(() => null), wt = task?.meta['cadre.worktree']; if (!task || !wt || !(await h.stat(wt))) continue
    meta[x.id] = task; tips[x.id] = (await G.git(h.run, wt, ['stash', 'create']).catch(() => '')).trim() || (await G.tip(h.run, wt, 'HEAD'))
  }
  const ids = Object.keys(tips), add: string[] = []
  for (let i = 0; i < ids.length; i++) for (const b of ids.slice(i + 1)) {
    const a = ids[i], key = `${a}|${b}`; if (seen.includes(key)) continue
    let files = await trial(h, d.root, tips[a], tips[b])
    if (files === undefined) { const pa = pathsOf(meta[a]), pb = pathsOf(meta[b]); files = pa.filter(p => pb.some(q => overlap(p, q))) }
    if (!files?.length) continue
    add.push(key)
    for (const [me, other] of [[a, b], [b, a]]) { const w = await worker(h, me); if (w) await pushDelta(h, w, modelText('context', `Heads-up: ${other} is changing ${files.slice(0, 5).join(', ')} at the same time. Keep your edits there small; whoever merges second updates onto the other.`)) }
  }
  for (let i = 0; i < eps.length; i++) for (const b of eps.slice(i + 1)) {   // two running epics of a milestone: their branches (what landed in each so far)
    const a = eps[i], key = `${a.id}|${b.id}`, files = seen.includes(key) ? null : await trial(h, d.root, a.branch, b.branch); if (!files?.length) continue
    add.push(key)
    for (const [me, other] of [[a, b], [b, a]]) for (const t of s.tasks.filter(t => t.epic === me.id)) { const w = await worker(h, t.id); if (w) await pushDelta(h, w, modelText('context', `Heads-up: the parallel epic ${other.id} (${other.title}) also changes ${files.slice(0, 5).join(', ')}. Keep your edits there small; the later landing merges onto the other.`)) }
  }
  if (add.length) await h.store.set(`cadre:${d.key}:collide`, [...seen, ...add].slice(-50))
}

// the core task landed: its files are locked for every other task of the plan (write jail); a needed change comes back as a blocked report, then a core-patch task
export async function coreLanded(h: Host, d: Deps, files: string[], contract?: string): Promise<void> {   // contract: the core task's interface, the plan block of every later brief (ADR 0022)
  const epic = (await h.board.read()).epic; if (!epic) return
  const all = [...new Set([...pathsOf({ meta: { 'cadre.paths': (await d.store.get(epic)).meta['cadre.corePaths'] ?? '' } }), ...files])]
  await d.store.setMeta(epic, { 'cadre.corePaths': JSON.stringify(all), ...(contract ? { 'cadre.coreContract': contract } : {}) }, d.actor); await lockCore(h, d)
}
export async function lockCore(h: Host, d: Deps, only?: string): Promise<void> {
  const s = await h.board.read(), files = s.epic ? pathsOf({ meta: { 'cadre.paths': (await d.store.get(s.epic)).meta['cadre.corePaths'] ?? '' } }) : []; if (!files.length) return
  const core = { ...(await policyOf(h)).core }
  for (const x of s.tasks.filter(x => (!only || x.id === only) && x.state !== 'done' && x.state !== 'cancelled')) { const wt = (await d.store.get(x.id).catch(() => null))?.meta['cadre.worktree']; if (wt) core[x.id] = files.map(f => `${wt}/${f}`) }
  await setPolicy(h, { core })
}

// ---- between epics of a milestone (ADR 0015 wave 2) ----
// an epic landed on the milestone: every other running epic takes the new tip (a throwaway worktree, CAS on its branch), then its running workers do;
// one that would conflict is left as it is: its own landing turns the conflict into a resolve task
export async function refreshEpics(h: Host, d: Deps, msTip: string, landedId: string): Promise<void> {
  for (const e of ((await h.board.read()).plan?.epics ?? []).filter(e => e.state === 'running' && e.id !== landedId)) {
    const head = await G.tip(h.run, d.root, e.branch).catch(() => ''); if (!head || (await trial(h, d.root, head, msTip)) !== null || (await G.ok(h.run, d.root, ['merge-base', '--is-ancestor', msTip, head]))) continue
    const tmp = `${d.wtRoot}/${d.key}.scratch/refresh-${e.id}`, next = await G.op(h, async () => {
      await h.run(['git', '-C', d.root, 'worktree', 'add', '-f', '--detach', tmp, head])
      try { if ((await h.run(['git', '-C', tmp, 'merge', '--no-ff', '--no-edit', '-m', `merge the milestone tip ${sha7(msTip)} into ${e.id}`, msTip])).exitCode) return ''; const n = await G.tip(h.run, tmp, 'HEAD'); return (await G.casRef(h.run, d.root, `refs/heads/${e.branch}`, n, head)) ? n : '' }
      finally { await h.run(['git', '-C', d.root, 'worktree', 'remove', '--force', tmp]) }
    })
    if (next) await refresh(h, d, next, '', e.id)
  }
}
// an epic (or a single plan) does not merge into its target: ONE refactor task in that epic whose tree holds the merge in progress (both sides, conflict markers);
// green, review and the squash land the resolution on the epic branch, then main completes the epic again. At most ROUNDS per epic; null = past the cap
export async function resolveTask(h: Host, d: Deps, epicId: string, from: string, onto: string, files: string[]): Promise<string | null> {
  const e = await d.store.get(epicId), n = num(e.meta['cadre.resolves']) + 1, ROUNDS = d.cfg.limits.rebaseRounds, s = await h.board.read(); if (n > ROUNDS) return null
  const other = await G.tip(h.run, d.root, await baseOf(h, onto))   // a landing that waits for the user's checkout is part of it; the close compares protected paths against this sha
  const title = `Resolve the merge conflict with ${onto}`, landed = (s.plan?.epics ?? []).filter(x => x.state === 'landed').map(x => `- ${x.id} ${x.title}`)
  const t = await d.store.createDraft({ title, type: 'refactor', parent: epicId, meta: { 'cadre.lane': 'lite', 'cadre.resolve': other, 'cadre.changelog': JSON.stringify({ none: true, reason: 'merge resolution' }) },
    description: [`Your working tree holds an unfinished merge of ${onto} into this branch${files.length ? `; the conflicts are marked in ${files.join(', ')}` : ''}. Resolve it so that both sides keep working, and keep every test green.`, `This side: ${e.title}\n${e.description.slice(0, 600)}`, ...(landed.length ? [`The other side (already on ${onto}):\n${landed.join('\n')}`] : [])].join('\n\n') })
  const wt = wtPath(d.wtRoot, d.key, t.id), br = taskBranch(d.reg.refactor?.commit ?? 'refactor', t.id, title), base = await G.tip(h.run, d.root, from)
  await G.op(h, async () => { await G.worktreeAdd(h.run, d.root, wt, br, base); await h.run(['git', '-C', wt, 'merge', '--no-ff', '--no-edit', other]) })   // the conflict is left in its tree
  await setup(h, d, t, wt).catch(x => h.log(`resolve setup: ${x}`))
  await d.store.setMeta(t.id, { 'cadre.worktree': wt, 'cadre.branch': br, 'cadre.base': base }, d.actor); await d.store.setMeta(epicId, { 'cadre.resolves': String(n) }, d.actor)
  await d.store.approve([t.id]); await mirror(h, d.store, d.reg); await apply(h, { kind: 'approve', id: t.id, at: await h.now(), actor: 'mod' }, pipeOf(d.reg))
  await decided(h, 'resolve', `${epicId}: merge with ${onto} conflicts${files.length ? ` on ${files.slice(0, 4).join(', ')}` : ''}; resolve task ${t.id} (attempt ${n}/${ROUNDS})`, t.id)
  return `${from} does not merge into ${onto}${files.length ? ` (conflicts in ${files.join(', ')})` : ''}. Resolve task ${t.id} was added to ${epicId} (attempt ${n}/${ROUNDS}): spawn TASK-${t.id}; when it is done, complete ${epicId} again.`
}

