// One target's push + pull (DESIGN 11.4 steps 2-3): per-field fnv64 hashes, upsert by stored rid, pull -> 3-way merge -> flags.
import type { Host } from '../../types'
import { emit } from '../../core/events'
import { agentsOf } from '../../core/board'
import { pushDelta } from '../../core/briefs'
import type { Task, TaskStore } from '../store'
import { call } from '../protocol'
import type { AdapterCfg } from '../protocol'
import { hash, merge } from './merge'
import type { Base } from './merge'

export interface Ctx { h: Host; store: TaskStore; name: string; a: AdapterCfg; target: string; t: { project?: string; url?: string; mapping?: any; direction?: string }; actor: string; first: boolean }
type Meta = Base & { rid?: string; etag?: string; skip?: number }
const key = (c: Ctx) => `cadre.sync.${c.target}`
export const metaOf = (c: Ctx, t: Task): Meta => { try { return { l: {}, r: {}, ...JSON.parse(t.meta[key(c)]) } } catch { return { l: {}, r: {} } } }
const save = (c: Ctx, id: string, m: Meta) => c.store.setMeta(id, { [key(c)]: JSON.stringify(m) }, `${c.actor}+sync`)

// records (DESIGN 11.4.2): a mission (type milestone) -> a version/milestone; a decision -> a comment on its linked task. Both push-only, text fields only.
export const recordKind = (t: Task): 'version' | 'comment' | undefined => t.type === 'milestone' ? 'version' : t.type === 'decision' ? 'comment' : undefined
export function fieldsOf(c: Ctx, t: Task): Record<string, string> {
  const m = c.t.mapping ?? {}
  if (recordKind(t)) return { title: t.title, description: t.description }
  return { title: t.title, description: t.description, acceptance: t.acceptance ?? '', priority: String(m.priority?.[t.priority] ?? t.priority), status: String(m.status?.[t.category] ?? t.category), type: String(m.type?.[t.type] ?? t.type) }
}
export async function flag(h: Host, taskId: string, f: string): Promise<void> {
  let added = false
  await h.board.update(s => { added = false; const t = s.tasks.find(x => x.id === taskId); if (!t || t.flags.includes(f)) return s; added = true; return { ...s, tasks: s.tasks.map(x => x.id === taskId ? { ...x, flags: [...x.flags, f] } : x) } })
  if (added) await emit(h, 'flag.raised', { taskId, flag: f }, { taskId, actor: 'sync' })
}
const unprio = (c: Ctx, v: string): number | undefined => { const e = Object.entries(c.t.mapping?.priority ?? {}).find(([, x]) => x === v); const n = e ? Number(e[0]) : Number(v); return Number.isInteger(n) && n >= 0 && n <= 4 ? n : undefined }

// pull first (so a concurrent remote edit is merged, not overwritten), then push every task whose hashes moved. Returns {pulled, pushed, next}.
export async function reconcile(c: Ctx, tasks: () => Promise<Task[]>, since: string | undefined, dir: string, pushSet: () => Promise<Task[]>): Promise<{ pulled: number; pushed: number; next?: string; deferred: number }> {
  const notes = new Map<string, string>(), touched = new Set<string>(); let pulled = 0, deferred = 0, next: string | undefined
  if (dir !== 'push') {
    const res = await call(c.h, c.name, c.a, 'pull', { project: c.t.project, since })
    next = res.next
    if (res.tasks?.length) {
      const all = await tasks()
      for (const rt of res.tasks as { rid: string; etag?: string; localId?: string; fields: Record<string, string> }[]) {
        const t = all.find(x => x.id === rt.localId) ?? all.find(x => metaOf(c, x).rid === rt.rid); if (!t || recordKind(t)) continue
        const m = metaOf(c, t); if (rt.etag && rt.etag === m.etag) continue   // dedupe: seen
        const r = merge(fieldsOf(c, t), rt.fields ?? {}, m), keys = Object.keys(r.pull)
        if (keys.length) {
          const patch: Record<string, any> = { ...r.pull }; if ('priority' in patch) { const p = unprio(c, patch.priority); if (p === undefined) delete patch.priority; else patch.priority = p }
          await c.store.update(t.id, patch, `${c.actor}+sync`); await flag(c.h, t.id, 'edited'); pulled++
          const bound = agentsOf(await c.h.bind.read(), t.id), msg = `sync: ${t.id} edited on the tracker: ${keys.map(k => `${k} = ${JSON.stringify(String(patch[k] ?? r.pull[k]).slice(0, 120))}`).join('; ')}`
          for (const a of bound) await pushDelta(c.h, a, msg)
        }
        const keep: Record<string, string> = {}   // the pulled remote value rides the task so `/cadre resolve <id> accept` can re-apply it (UI-DESIGN 5.4)
        for (const f of r.conflict) { const v = f === 'priority' ? unprio(c, rt.fields[f]) : rt.fields[f]; if (v !== undefined) keep[`cadre.remote.${f}`] = String(v) }
        if (r.drift) { const sm = Object.entries(c.t.mapping?.status ?? {}).find(([, x]) => x === rt.fields.status)?.[0]; keep['cadre.remote.status'] = sm ?? String(rt.fields.status) }
        if (Object.keys(keep).length) await c.store.setMeta(t.id, keep, `${c.actor}+sync`)
        if (r.conflict.length) { notes.set(t.id, `cadre: ${r.conflict.join(', ')} changed on both sides; the beads value was kept`); await flag(c.h, t.id, 'conflict') }
        if (r.drift) await flag(c.h, t.id, 'drift')
        if (r.conflict.length || r.drift) touched.add(t.id)   // the pull's own writes are +sync (skipped by the journal scan): push these back this cycle
        await save(c, t.id, { ...m, rid: rt.rid, etag: rt.etag, ...r.next })
      }
    }
  }
  let pushed = 0
  if (dir !== 'pull') {
    const items = []
    const set = await pushSet(), have = new Set(set.map(x => x.id))
    for (const id of touched) if (!have.has(id)) set.push(await c.store.get(id))
    for (const t of set) {
      const m = metaOf(c, t); if (m.skip || t.category === 'draft' || t.type === 'gate') continue
      const fields = fieldsOf(c, t), changed = Object.keys(fields).filter(f => hash(fields[f]) !== m.l[f])
      const rk = recordKind(t); let on: string | undefined
      if (rk === 'comment') { const link = t.meta.link, lt = link && (await tasks()).find(x => x.id === link); on = lt ? metaOf(c, lt).rid : undefined; if (!on) { deferred++; continue } }   // the linked task is not on the tracker yet: next cycle
      if (changed.length || !m.rid) items.push({ t, m, fields, changed, note: notes.get(t.id), rk, on })
    }
    if (items.length) {
      const res = await call(c.h, c.name, c.a, 'push', { project: c.t.project, tasks: items.map(i => ({ localId: i.t.id, rid: i.m.rid, etag: i.m.etag, changed: i.changed, fields: i.fields, ...(i.note ? { note: i.note } : {}), ...(i.rk ? { kind: i.rk, ...(i.on ? { on: i.on } : {}) } : {}) })) })
      for (const r of res.results as { localId: string; rid: string; etag?: string }[]) {
        const i = items.find(x => x.t.id === r.localId); if (!i) continue
        const hs = Object.fromEntries(Object.entries(i.fields).map(([f, v]) => [f, hash(v)]))
        await save(c, i.t.id, { rid: r.rid, etag: r.etag, l: hs, r: { ...i.m.r, ...Object.fromEntries(i.changed.map(f => [f, hs[f]])) } })
        if (c.first && !i.t.externalRef) await c.store.setExternalRef(i.t.id, `${c.target}:${r.rid}`, `${c.actor}+sync`); pushed++
      }
    }
  }
  return { pulled, pushed, next, deferred }
}

files.ui/notify.ts:
// Notification policy (UI-DESIGN 4): level from kind + severity + needsHuman (never stored), dedupe by key, <=1 toast / 8 s with merging, OS notify <=1/item and <=3 / 15 min,
// escalation after ui.escalateAfterMs unless acked, status line = top attention item only. State lives in the cadre.ui atom; side effects run after the CAS settles.
import type { CadreEvent, Host } from '../types'
import { CFG, attention, read } from './model'
import { clip } from './layout'
import { needsOf } from './v2/facts'
import { holds, yoloOn } from '../core/decide'

export type Level = 0 | 1 | 2 | 3   // silent . · band o · toast * · notify !
// yolo: main answers blocked questions and the flags drive does not hold on, so those never reach the human (no toast, no "press 1")
export const quietUnderYolo = (e: CadreEvent): boolean => (e.type === 'flag.raised' && !holds(String(e.data.flag))) || (e.type === 'task.transitioned' && String(e.data.to ?? e.data.state) === 'blocked')
export function levelOf(e: CadreEvent, yolo = false): Level {
  const d = e.data, st = String(d.state ?? d.to ?? '')
  if (yolo && quietUnderYolo(e)) return 0
  switch (e.type) {
    case 'approval.pending': case 'flag.raised': return 3
    case 'task.transitioned': return st === 'blocked' ? 3 : st === 'done' || d.from === 'review' && st === 'active' ? 1 : e.severity === 'crit' ? 2 : 0
    case 'check.ran': return 1
    case 'sync.state_changed': return st === 'ok' && !d.conflicts ? 1 : 2
    case 'drive.status': return st === 'paused' || st === 'finished' || st === 'stopped' ? 3 : 0
    case 'agent.unbound': return d.reason === 'stale' ? 1 : 0
    case 'plan.landed': return d.on ? 2 : 0   // an epic of a milestone landed on the milestone branch (the milestone's own landing is drive's toast)
    case 'init.stage': return st === 'proposed' ? 2 : 1   // done / Claude working: in the log, no toast
    case 'cost.updated': return d.threshold ? 2 : 0
    default: return e.needsHuman ? 3 : e.severity === 'crit' ? 2 : 0
  }
}
// matrix text (no secrets, D7) + dedupe key; undefined = no toast
export function textOf(e: CadreEvent): { text: string; key: string } | undefined {
  const d = e.data, id = e.taskId ?? String(d.taskId ?? ''), st = String(d.state ?? d.to ?? '')
  switch (e.type) {
    case 'approval.pending': return { text: `Plan ${d.planId} ready for approval · press 1`, key: `approve:${d.planId}:${d.rev ?? ''}` }
    case 'task.transitioned': return st === 'blocked' ? { text: `${id} blocked: needs an answer`, key: `q:${id}:${d.hash ?? ''}` } : undefined
    case 'flag.raised': return { text: `${id} flagged ${d.flag} · press 1`, key: `flag:${id}:${d.flag}` }
    case 'sync.state_changed': return st === 'ok' ? { text: `${d.target} reconnected${d.conflicts ? ` · ${d.conflicts} conflict` : ''}`, key: `off:${d.target}` } : { text: `${d.target} ${st} · retrying`, key: `off:${d.target}` }
    case 'drive.status': if (st === 'stopped') return { text: clip(`drive stopped${d.reason ? ` · ${d.reason}` : ''} · 0: resume`, 60), key: `drive:stopped:${e.at}` }   // one toast per stop
      return st === 'paused' || st === 'finished' ? { text: st === 'paused' ? `Drive paused${d.reason ? `: ${d.reason}` : ''}` : 'Landed on dev ✓', key: `drive:${st}` } : undefined
    case 'plan.landed': return d.on ? { text: `Epic ${d.planId} landed on ${d.on} ✓`, key: `landed:${d.planId}` } : undefined
    case 'cost.updated': return d.threshold ? { text: `Drive at ${d.threshold}% of token budget`, key: `cost:${d.threshold}` } : undefined
    case 'init.stage': return st === 'proposed' ? { text: 'Init diff ready · /cadre open init', key: `init:${d.stage}` } : undefined
    default: return undefined
  }
}
const CLOSE: Partial<Record<CadreEvent['type'], (e: CadreEvent) => string>> = { 'flag.resolved': e => `flag:${e.taskId}:${e.data.flag}`, 'sync.state_changed': e => (e.data.state === 'ok' ? `off:${e.data.target}` : '') }

export const ack = (h: Host) => h.now().then(n => h.ui.update(u => ({ ...u, ack: n })))   // composer submit, any /cadre, a cadre press, pane focus

async function toast(h: Host, text: string, now: number): Promise<void> {
  let direct = false, first = false, wait = 0
  await h.ui.update(u => {
    const q = (u.q as string[] | undefined) ?? [], dt = now - ((u.lt as number | undefined) ?? -1e9)
    direct = dt >= 8000 && !q.length; first = !direct && !q.length; wait = Math.max(0, 8000 - dt)
    return direct ? { ...u, lt: now } : { ...u, q: [...q, text] }
  })
  if (direct) h.ops?.toast(text, { timeoutMs: 6000 })
  else if (first) h.ops?.after(wait, async () => {   // coalesce what arrived inside the window
    let q: string[] = []
    await h.ui.update(u => { q = (u.q as string[]) ?? []; return { ...u, q: [], lt: now + wait } })
    if (q.length) h.ops?.toast(q.length === 1 ? q[0] : `${q.length} updates: ${q.join(' · ')}`, { timeoutMs: 6000 })
  })
}
async function notify(h: Host, key: string, text: string, now: number): Promise<void> {
  const cfg = { ...CFG, ...((await h.ui.read()).cfg as object) }
  if (cfg.notify === 'off' || !h.ops || await h.ops.focused()) return
  let ok = false
  await h.ui.update(u => {
    const nt = ((u.nt as number[] | undefined) ?? []).filter(x => now - x < 900_000), sent = (u.nf as Record<string, number> | undefined) ?? {}
    ok = !(key in sent) && nt.length < 3
    return ok ? { ...u, nt: [...nt, now], nf: { ...sent, [key]: now } } : u
  })
  if (ok && !(await h.ops.notify(text, { title: 'cadre' })).isSent) h.ops.toast(text, { timeoutMs: 6000 })
}
// status line: what the human owes (ui/v2/facts.needsOf, the band's own test), else a problem state; cleared when none (never the command, so never a code)
// "press 1" only where 1 opens a dialog: a run's progress card is no need (live 0.11.0: "init · 2/8 done · Claude is on it · press 1" opened nothing)
export async function syncStatus(h: Host): Promise<void> { const v = await read(h), top = needsOf(v)[0] ?? attention(v).find(i => !i.d); h.ops?.status(top ? `${top.text}${top.d ? ' · press 1' : ''}` : undefined) }

// subscribed to core/events: one call per emitted event
export async function onEvent(h: Host, e: CadreEvent): Promise<void> {
  const k = CLOSE[e.type]?.(e), lv = levelOf(e, yoloOn((await h.board.read()).drive)), t = textOf(e)
  if (k) await h.ui.update(u => { const { [k]: _x, ...rest } = (u.open as Record<string, number> | undefined) ?? {}; return { ...u, open: rest } })
  if (lv >= 2 && t) {
    let fresh = false
    await h.ui.update(u => { const o = (u.open as Record<string, number> | undefined) ?? {}; fresh = !(t.key in o); return fresh ? { ...u, open: { ...o, [t.key]: e.at } } : u })
    if (fresh) {
      await toast(h, t.text, e.at)
      if (lv === 3) {
        if (e.type === 'drive.status') await notify(h, t.key, t.text, e.at)   // drive paused/finished: immediately
        else h.ops?.after(((await h.ui.read()).cfg as { escalateAfterMs?: number } | undefined)?.escalateAfterMs ?? CFG.escalateAfterMs, async () => {
          const u = await h.ui.read()
          if (t.key in ((u.open as object) ?? {}) && ((u.ack as number | undefined) ?? 0) < e.at) await notify(h, t.key, t.text, await h.now())
        })
      }
    }
  }
  await syncStatus(h)
}

files.ui/tokens.ts:
// UI v2 tokens (BRAND §3, §6, §7): the ONLY file that may hold literal theme keys, glyphs or colours for v2 code. Pure; no host reads here.
// The render hooks cannot read env or files, so session.start resolves `ascii`/`theme`/`flash`/`density` once into the ui atom (`cfg`) and `readCfg` reads them back.

export type Role = 'fg' | 'muted' | 'accent' | 'attention' | 'success' | 'danger' | 'rule'
export const ROLE: Record<Role, string> = { fg: 'text', muted: 'inactive', accent: 'claude', attention: 'warning', success: 'success', danger: 'error', rule: 'subtle' }
export const color = (r: Role): string => ROLE[r]

export type GlyphK = 'attn' | 'run' | 'ready' | 'wait' | 'done' | 'fail' | 'skip'
const GLYPH: Record<GlyphK, [string, string, Role]> = {   // unicode, ascii, colour role
  attn: ['!', '!', 'attention'], run: ['›', '>', 'accent'], ready: ['○', 'o', 'fg'], wait: ['·', '-', 'muted'],
  done: ['✓', '+', 'success'], fail: ['✗', 'x', 'danger'], skip: ['–', '.', 'muted'],
}
export const glyph = (k: GlyphK, ascii: boolean): string => GLYPH[k][ascii ? 1 : 0]
export const glyphRole = (k: GlyphK): Role => GLYPH[k][2]
export const RULE = ['─', '-'] as const
export const rule = (n: number, ascii: boolean): string => RULE[ascii ? 1 : 0].repeat(Math.max(0, n))
export const edge = (k: 'blocks' | 'cond', ascii: boolean): string => (ascii ? (k === 'blocks' ? '->' : '..>') : k === 'blocks' ? '─→' : '┄→')
export const cursor = (ascii: boolean): string => (ascii ? '|' : '│')
const BLOCK: Record<Cell, [string, string]> = { work: ['█', '#'], review: ['▓', '='], offline: ['░', ':'], attention: ['▒', '%'], failure: ['█', 'X'] }
export const block = (c: Cell, ascii: boolean): string => BLOCK[c][ascii ? 1 : 0]
export const ELL = '…', SEP = ' · ', ARROWS = '↑↓←→'   // text marks: truncation, fact separator, key-hint arrows
// ASCII mode (BRAND §6): every width-1 mark that is not ASCII maps to an ASCII mark of the same width, applied once to a finished frame
const ASC: Record<string, string> = { '·': '-', '…': '~', '↑': '^', '↓': 'v', '←': '<', '→': '>', '✓': '+', '✗': 'x', '─': '-', '│': '|', '┄': '.', '–': '.', '›': '>' }
export const asciiText = (s: string): string => s.replace(/[·…↑↓←→✓✗─│┄–›]/g, c => ASC[c])
export const BLOCKS = '█▓▒░'   // Raster cells only (width-1, BMP)
// every glyph v2 may draw, for the acceptance lint: BRAND §6 + the rule + Raster blocks + the separators of §5 + the cursor
export const ALLOWED = new Set([...Object.values(GLYPH).flatMap(g => [g[0], g[1]]), RULE[0], RULE[1], ...BLOCKS, ...ARROWS, ELL, '—', '│', '→', '┄', ...Object.values(BLOCK).flat(), '|', '>', '.'])

// §7: spacing scale, indent, gutters, fixed task-row columns
export const SPACE = [0, 1, 2, 3, 4, 6, 8] as const
export const INDENT = 2, DETAIL = 4, GUTTER = 1, BTN_GAP = 2
export const COL = { glyph: 1, id: 3, role: 9, time: 6, ctx: 8, actTime: 7 } as const

// §3.3: Raster palettes (0x00RRGGBB), default-foreground when the theme is unknown
export type Cell = 'work' | 'review' | 'offline' | 'attention' | 'failure'
export const DEFAULT_FG = 0x01000000
const PAL: Record<'dark' | 'light', Record<Cell, number>> = {
  dark: { work: 0xd77757, review: 0x8a8f98, offline: 0x4b4f57, attention: 0xe5c07b, failure: 0xe06c75 },
  light: { work: 0xb4532e, review: 0x5c6370, offline: 0xc8ccd2, attention: 0x9a6a00, failure: 0xb3261e },
}
export type Theme = 'dark' | 'light' | 'unknown'
// `$.config.list()` rows: the value vocabulary is untyped, so match loosely ("light", "light-daltonized", "dark-ansi"...)
export const themeOf = (rows?: { key: string; value?: unknown }[]): Theme => {
  const v = String(rows?.find(r => r.key === 'theme')?.value ?? '')
  return /^light/.test(v) ? 'light' : /^dark/.test(v) ? 'dark' : 'unknown'
}
export const raster = (c: Cell, t: Theme): number => (t === 'unknown' ? DEFAULT_FG : PAL[t][c])

