  } else if (v.ui.held && !v.sec?.run) l1 = [g(v, 'wait'), muted(clip(` Stopped${SEP}type anything in the prompt to go on`, w - 2))]   // commands/agentrun.pump: a submit is refused until the human sends input
  else if (v.ui.halt && !v.sec?.run) l1 = [g(v, 'wait'), muted(clip(` ${v.ui.halt}`, w - 2))]   // a setup cut short in an earlier session (commands/agentrun.halt)
