  for (const p of pipe) { const l = lines[lines.length - 1]; if (l.length && lw(l) + 2 + lw(p) > w - 2) lines.push([]); const x = lines[lines.length - 1]; if (x.length) x.push(S('  ')); x.push(...p) }
