  const rel = [ups.length ? `after ${ups.join(' ')}` : '', downs.length ? `unblocks ${downs.join(' ')}` : '', t.owner && t.state !== 'done' ? t.owner.split(' ')[0] : ''].filter(Boolean).join(`${SEP}`)
